const a={"ko-first-u01.title":"Hewan","ko-first-u01.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u01.w.0":"kucing","ko-first-u01.w.1":"anak anjing","ko-first-u01.w.2":"ikan","ko-first-u01.w.3":"burung","ko-first-u01.w.4":"sapi","ko-first-u01.w.5":"babi","ko-first-u02.title":"Makanan","ko-first-u02.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u02.w.0":"apel","ko-first-u02.w.1":"pisang","ko-first-u02.w.2":"susu","ko-first-u02.w.3":"roti","ko-first-u02.w.4":"telur","ko-first-u02.w.5":"nasi","ko-first-u03.title":"Mainan","ko-first-u03.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u03.w.0":"bola","ko-first-u03.w.1":"mobil","ko-first-u03.w.2":"boneka beruang","ko-first-u03.w.3":"layang-layang","ko-first-u03.w.4":"kereta","ko-first-u03.w.5":"perahu","ko-first-u04.title":"Tubuh","ko-first-u04.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u04.w.0":"mata","ko-first-u04.w.1":"telinga","ko-first-u04.w.2":"hidung","ko-first-u04.w.3":"mulut","ko-first-u04.w.4":"tangan","ko-first-u04.w.5":"kaki","ko-first-u05.title":"Warna","ko-first-u05.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u05.w.0":"merah","ko-first-u05.w.1":"biru","ko-first-u05.w.2":"kuning","ko-first-u05.w.3":"hijau","ko-first-u05.w.4":"hitam","ko-first-u05.w.5":"putih","ko-first-u06.title":"Keluarga","ko-first-u06.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u06.w.0":"ibu","ko-first-u06.w.1":"ayah","ko-first-u06.w.2":"bayi","ko-first-u06.w.3":"nenek","ko-first-u06.w.4":"kakek","ko-first-u06.w.5":"anak","ko-first-u07.title":"Di rumah","ko-first-u07.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u07.w.0":"rumah","ko-first-u07.w.1":"tempat tidur","ko-first-u07.w.2":"kursi","ko-first-u07.w.3":"pintu","ko-first-u07.w.4":"buku","ko-first-u07.w.5":"cangkir","ko-first-u08.title":"Di luar","ko-first-u08.tip":"Lihat gambarnya, dengarkan, lalu ucapkan kata Koreanya bersama-sama. Tidak apa-apa kalau anak Anda belum bisa membaca.","ko-first-u08.w.0":"matahari","ko-first-u08.w.1":"bulan","ko-first-u08.w.2":"bintang","ko-first-u08.w.3":"pohon","ko-first-u08.w.4":"bunga","ko-first-u08.w.5":"hujan"},k={"ko-kinder-u01.title":"Huruf vokal ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":'Huruf Korea bergabung menjadi blok. ㅇ di awal tidak berbunyi, jadi 아 terdengar seperti "a" saja. Ucapkan 아, 어, 오, 우, 이 dengan mulut terbuka lebar!',"ko-kinder-u01.w.0":"bayi","ko-kinder-u01.w.1":"es krim","ko-kinder-u01.w.2":"ibu","ko-kinder-u01.w.3":"bebek","ko-kinder-u01.w.4":"mentimun","ko-kinder-u01.w.5":"susu","ko-kinder-u01.w.6":"payung","ko-kinder-u01.w.7":"gigi","ko-kinder-u01.s.0":"Bayinya sedang tidur.","ko-kinder-u01.s.1":"Ada bebek datang.","ko-kinder-u01.s.2":"Susu, ya.","ko-kinder-u02.title":"Huruf ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"Satu blok huruf adalah konsonan ditambah vokal: ㄱ + ㅏ = 가. Ketuk setiap kartu huruf untuk mendengar namanya, lalu baca bloknya bersama-sama.","ko-kinder-u02.w.0":"tas","ko-kinder-u02.w.1":"daging","ko-kinder-u02.w.2":"sepatu","ko-kinder-u02.w.3":"kupu-kupu","ko-kinder-u02.w.4":"pohon","ko-kinder-u02.w.5":"lagu","ko-kinder-u02.w.6":"tupai","ko-kinder-u02.w.7":"biji ek","ko-kinder-u02.s.0":"Kupu-kupunya terbang.","ko-kinder-u02.s.1":"Tasnya besar.","ko-kinder-u02.s.2":"Tupainya sedang makan.","ko-kinder-u03.title":"Huruf ㄹ ㅁ ㅂ","ko-kinder-u03.tip":'Bunyi ㄹ ada di antara "r" dan "l". ㅁ mirip mulut yang tertutup — dan kamu memang menutup bibir untuk mengucapkannya!',"ko-kinder-u03.w.0":"ramyeon (mi)","ko-kinder-u03.w.1":"lemon","ko-kinder-u03.w.2":"kuda","ko-kinder-u03.w.3":"topi","ko-kinder-u03.w.4":"pelangi","ko-kinder-u03.w.5":"pisang","ko-kinder-u03.w.6":"bus","ko-kinder-u03.w.7":"hujan","ko-kinder-u03.s.0":"Topinya cantik.","ko-kinder-u03.s.1":"Busnya datang.","ko-kinder-u03.s.2":"Hujan turun.","ko-kinder-u04.title":"Huruf ㅅ ㅇ ㅈ","ko-kinder-u04.tip":'ㅇ tidak berbunyi di awal blok (아, 오), tetapi di bawah berbunyi "ng" (방). ㅅ mirip tenda kecil: 사, 소.',"ko-kinder-u04.w.0":"singa","ko-kinder-u04.w.1":"apel","ko-kinder-u04.w.2":"sapi","ko-kinder-u04.w.3":"semangka","ko-kinder-u04.w.4":"jam","ko-kinder-u04.w.5":"mobil","ko-kinder-u04.w.6":"jus","ko-kinder-u04.w.7":"Bumi","ko-kinder-u04.s.0":"Singanya besar.","ko-kinder-u04.s.1":"Jus, ya.","ko-kinder-u04.s.2":"Semangkanya enak.","ko-kinder-u05.title":"Huruf ㅊ ㅋ ㅌ","ko-kinder-u05.tip":'ㅊ, ㅋ, ㅌ adalah huruf "berembus": ㅋ adalah ㄱ dengan satu garis tambahan dan embusan napas tambahan. Taruh tanganmu di depan mulut dan rasakan!',"ko-kinder-u05.w.0":"rok","ko-kinder-u05.w.1":"keju","ko-kinder-u05.w.2":"hidung","ko-kinder-u05.w.3":"gajah","ko-kinder-u05.w.4":"kue kering","ko-kinder-u05.w.5":"kelinci","ko-kinder-u05.w.6":"tomat","ko-kinder-u05.w.7":"truk","ko-kinder-u05.s.0":"Kelincinya melompat.","ko-kinder-u05.s.1":"Belalai gajah panjang.","ko-kinder-u05.s.2":"Satu kue, ya.","ko-kinder-u06.title":"Huruf ㅍ ㅎ","ko-kinder-u06.tip":'ㅎ berbunyi seperti "h" — 하, 호, 후, seperti tawa kecil. Sekarang kamu sudah tahu ke-14 konsonan dasar!',"ko-kinder-u06.w.0":"anggur","ko-kinder-u06.w.1":"pizza","ko-kinder-u06.w.2":"ombak","ko-kinder-u06.w.3":"penguin","ko-kinder-u06.w.4":"kuda nil","ko-kinder-u06.w.5":"matahari","ko-kinder-u06.w.6":"harimau","ko-kinder-u06.w.7":"tisu","ko-kinder-u06.s.0":"Penguinnya berjalan.","ko-kinder-u06.s.1":"Harimaunya sedang tidur.","ko-kinder-u06.s.2":"Anggurnya enak.","ko-kinder-u07.title":"Huruf vokal ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":'Satu garis tambahan menambahkan bunyi "y": ㅏ (a) → ㅑ (ya), ㅗ (o) → ㅛ (yo). ㅐ dan ㅔ sekarang bunyinya hampir sama — orang Korea pun sering tertukar!',"ko-kinder-u07.w.0":"bisbol","ko-kinder-u07.w.1":"rubah","ko-kinder-u07.w.2":"memasak","ko-kinder-u07.w.3":"hantu","ko-kinder-u07.w.4":"ulat","ko-kinder-u07.w.5":"anjing","ko-kinder-u07.w.6":"pir","ko-kinder-u07.w.7":"kepiting","ko-kinder-u07.s.0":"Rubahnya tersenyum.","ko-kinder-u07.s.1":"Kepitingnya berjalan.","ko-kinder-u07.s.2":"Aku sedang memasak.","ko-kinder-u08.title":"Huruf bawah (batchim)","ko-kinder-u08.tip":"Konsonan bisa duduk di bagian bawah blok: ㄱ + ㅗ + ㅁ = 곰. Huruf bawah itu disebut batchim (받침). Sekarang kamu bisa membaca hampir semua kata Korea!","ko-kinder-u08.w.0":"beruang","ko-kinder-u08.w.1":"bola","ko-kinder-u08.w.2":"salju","ko-kinder-u08.w.3":"gunung","ko-kinder-u08.w.4":"roti","ko-kinder-u08.w.5":"bintang","ko-kinder-u08.w.6":"bulan","ko-kinder-u08.w.7":"air","ko-kinder-u08.s.0":"Beruangnya sedang tidur.","ko-kinder-u08.s.1":"Salju turun.","ko-kinder-u08.s.2":"Air, ya."},u={"ko-g12-u01.title":"Salam","ko-g12-u01.tip":"Membungkuklah sedikit saat mengucapkan 안녕하세요 — begitulah cara orang Korea memberi salam. Kepada teman dekat, cukup bilang 안녕!","ko-g12-u01.w.0":"halo","ko-g12-u01.w.1":"selamat jalan (kepada yang pergi)","ko-g12-u01.w.2":"terima kasih","ko-g12-u01.w.3":"maaf","ko-g12-u01.w.4":"ya","ko-g12-u01.w.5":"tidak","ko-g12-u01.w.6":"teman","ko-g12-u01.w.7":"guru","ko-g12-u01.w.8":"selamat tidur","ko-g12-u01.s.0":"Halo, Bu Guru.","ko-g12-u01.s.1":"Ya, terima kasih.","ko-g12-u01.s.2":"Tidak, tidak apa-apa.","ko-g12-u01.s.3":"Aku benar-benar minta maaf.","ko-g12-u01.s.4":"Hai, teman!","ko-g12-u01.s.5":"Selamat tidur, Ibu.","ko-g12-u02.title":"Angka 1–10","ko-g12-u02.tip":"Bahasa Korea punya dua kelompok angka. 하나, 둘, 셋 dipakai untuk menghitung benda dan menyebut umur. Hitung jarimu dengan angka ini!","ko-g12-u02.w.0":"satu","ko-g12-u02.w.1":"dua","ko-g12-u02.w.2":"tiga","ko-g12-u02.w.3":"empat","ko-g12-u02.w.4":"lima","ko-g12-u02.w.5":"enam","ko-g12-u02.w.6":"tujuh","ko-g12-u02.w.7":"delapan","ko-g12-u02.w.8":"sembilan","ko-g12-u02.w.9":"sepuluh","ko-g12-u02.s.0":"Satu, dua, tiga!","ko-g12-u02.s.1":"Empat, lima, enam.","ko-g12-u02.s.2":"Tujuh, delapan, sembilan, sepuluh.","ko-g12-u02.s.3":"Umurku lima tahun.","ko-g12-u02.s.4":"Jariku ada sepuluh.","ko-g12-u02.s.5":"Satu lagi, ya.","ko-g12-u03.title":"Warna","ko-g12-u03.tip":"Setiap kata warna berakhiran 색 (warna). Tunjuk benda di sekitarmu dan sebutkan warnanya: 빨간색!","ko-g12-u03.w.0":"merah","ko-g12-u03.w.1":"biru","ko-g12-u03.w.2":"kuning","ko-g12-u03.w.3":"hijau","ko-g12-u03.w.4":"ungu","ko-g12-u03.w.5":"oranye","ko-g12-u03.w.6":"merah muda","ko-g12-u03.w.7":"hitam","ko-g12-u03.w.8":"putih","ko-g12-u03.s.0":"Apel berwarna merah.","ko-g12-u03.s.1":"Langitnya biru.","ko-g12-u03.s.2":"Pisang berwarna kuning.","ko-g12-u03.s.3":"Daun berwarna hijau.","ko-g12-u03.s.4":"Anggur berwarna ungu.","ko-g12-u03.s.5":"Aku suka merah muda.","ko-g12-u04.title":"Keluarga","ko-g12-u04.tip":'Orang Korea bilang 우리 (kami/kita) bukan "aku punya" untuk keluarga dan rumah: 우리 엄마, 우리 집. Kedengarannya hangat dan akrab.',"ko-g12-u04.w.0":"keluarga","ko-g12-u04.w.1":"ibu","ko-g12-u04.w.2":"ayah","ko-g12-u04.w.3":"nenek","ko-g12-u04.w.4":"kakek","ko-g12-u04.w.5":"adik","ko-g12-u04.w.6":"bayi","ko-g12-u04.w.7":"anak anjing","ko-g12-u04.s.0":"Ini keluargaku.","ko-g12-u04.s.1":"Ibu, aku sayang Ibu.","ko-g12-u04.s.2":"Ayah tinggi.","ko-g12-u04.s.3":"Nenek tersenyum.","ko-g12-u04.s.4":"Adikku menangis.","ko-g12-u04.s.5":"Anak anjing juga keluarga.","ko-g12-u05.title":"Hewan","ko-g12-u05.tip":"Suara hewan dalam bahasa Korea lucu sekali: kucing bilang 야옹, anjing bilang 멍멍, katak bilang 개굴개굴. Coba tirukan!","ko-g12-u05.w.0":"kucing","ko-g12-u05.w.1":"monyet","ko-g12-u05.w.2":"jerapah","ko-g12-u05.w.3":"tikus","ko-g12-u05.w.4":"ular","ko-g12-u05.w.5":"ayam","ko-g12-u05.w.6":"domba","ko-g12-u05.w.7":"kura-kura","ko-g12-u05.w.8":"katak","ko-g12-u05.s.0":"Kucing bilang meong.","ko-g12-u05.s.1":"Leher jerapah panjang.","ko-g12-u05.s.2":"Monyet makan pisang.","ko-g12-u05.s.3":"Kura-kura itu lambat.","ko-g12-u05.s.4":"Katak melompat.","ko-g12-u05.s.5":"Domba makan rumput.","ko-g12-u06.title":"Buah","ko-g12-u06.tip":"배 artinya pir — juga perahu dan perut! Gambarnya yang memberi tahu artinya.","ko-g12-u06.w.0":"apel","ko-g12-u06.w.1":"pisang","ko-g12-u06.w.2":"stroberi","ko-g12-u06.w.3":"anggur","ko-g12-u06.w.4":"semangka","ko-g12-u06.w.5":"jeruk mandarin","ko-g12-u06.w.6":"persik","ko-g12-u06.w.7":"pir","ko-g12-u06.w.8":"kiwi","ko-g12-u06.s.0":"Stroberinya merah.","ko-g12-u06.s.1":"Jeruknya manis.","ko-g12-u06.s.2":"Aku suka persik.","ko-g12-u06.s.3":"Semangkanya besar sekali.","ko-g12-u06.s.4":"Anggur, ya.","ko-g12-u06.s.5":"Kiwi berwarna hijau.","ko-g12-u07.title":"Makanan","ko-g12-u07.tip":"Sebelum makan, orang Korea bilang 잘 먹겠습니다 (aku akan makan dengan lahap), dan sesudah makan 잘 먹었습니다. Coba saat makan nanti!","ko-g12-u07.w.0":"nasi","ko-g12-u07.w.1":"kimchi","ko-g12-u07.w.2":"sup","ko-g12-u07.w.3":"gimbap (nasi gulung)","ko-g12-u07.w.4":"kue beras","ko-g12-u07.w.5":"pangsit","ko-g12-u07.w.6":"telur","ko-g12-u07.w.7":"ikan (untuk dimakan)","ko-g12-u07.w.8":"sendok","ko-g12-u07.w.9":"sumpit","ko-g12-u07.s.0":"Aku makan nasi.","ko-g12-u07.s.1":"Kimchinya pedas.","ko-g12-u07.s.2":"Pangsitnya enak.","ko-g12-u07.s.3":"Supnya panas.","ko-g12-u07.s.4":"Aku makan pakai sumpit.","ko-g12-u07.s.5":"Gimbap, ya.","ko-g12-u07.s.6":"Aku lapar.","ko-g12-u08.title":"Tubuh","ko-g12-u08.tip":'Main "Simon berkata" dalam bahasa Korea: 코! 귀! 머리! Sentuh bagian tubuh yang kamu dengar.',"ko-g12-u08.w.0":"kepala","ko-g12-u08.w.1":"mata","ko-g12-u08.w.2":"hidung","ko-g12-u08.w.3":"mulut","ko-g12-u08.w.4":"telinga","ko-g12-u08.w.5":"tangan","ko-g12-u08.w.6":"telapak kaki","ko-g12-u08.w.7":"kaki (tungkai)","ko-g12-u08.w.8":"lengan","ko-g12-u08.s.0":"Mataku ada dua.","ko-g12-u08.s.1":"Sentuh hidungmu.","ko-g12-u08.s.2":"Aku mencuci tangan.","ko-g12-u08.s.3":"Buka mulutmu lebar-lebar.","ko-g12-u08.s.4":"Kepalaku sakit.","ko-g12-u08.s.5":"Kakiku panjang.","ko-g12-u09.title":"Sekolah","ko-g12-u09.tip":"Di Korea, murid memanggil gurunya 선생님 — tidak pernah hanya namanya. 님 adalah akhiran sopan yang menunjukkan rasa hormat.","ko-g12-u09.w.0":"sekolah","ko-g12-u09.w.1":"ruang kelas","ko-g12-u09.w.2":"pensil","ko-g12-u09.w.3":"penghapus","ko-g12-u09.w.4":"buku tulis","ko-g12-u09.w.5":"gunting","ko-g12-u09.w.6":"meja belajar","ko-g12-u09.w.7":"papan tulis","ko-g12-u09.w.8":"PR","ko-g12-u09.s.0":"Aku pergi ke sekolah.","ko-g12-u09.s.1":"Aku punya pensil.","ko-g12-u09.s.2":"Tolong pinjami aku penghapus.","ko-g12-u09.s.3":"Aku menulis di buku tulis.","ko-g12-u09.s.4":"PR-ku banyak.","ko-g12-u09.s.5":"Bu Guru, aku mau bertanya!","ko-g12-u10.title":"Di rumah","ko-g12-u10.tip":"Orang Korea melepas sepatu di pintu sebelum masuk. Lantainya sering hangat (pemanas ondol) — nyaman sekali!","ko-g12-u10.w.0":"rumah","ko-g12-u10.w.1":"kamar","ko-g12-u10.w.2":"dapur","ko-g12-u10.w.3":"kamar mandi","ko-g12-u10.w.4":"lampu","ko-g12-u10.w.5":"pintu","ko-g12-u10.w.6":"sofa","ko-g12-u10.w.7":"kulkas","ko-g12-u10.w.8":"TV","ko-g12-u10.s.0":"Rumah kami kecil.","ko-g12-u10.s.1":"Ini kamarku.","ko-g12-u10.s.2":"Ibu ada di dapur.","ko-g12-u10.s.3":"Aku menyalakan lampu.","ko-g12-u10.s.4":"Aku duduk di sofa.","ko-g12-u10.s.5":"Kamar mandinya di mana?","ko-g12-u11.title":"Pakaian","ko-g12-u11.tip":'Bahasa Korea memakai kata kerja berbeda untuk "memakai": 입어요 untuk baju, 신어요 untuk kaus kaki dan sepatu, 써요 untuk topi. Lucu, kan?',"ko-g12-u11.w.0":"baju","ko-g12-u11.w.1":"kaus","ko-g12-u11.w.2":"celana","ko-g12-u11.w.3":"rok","ko-g12-u11.w.4":"kaus kaki","ko-g12-u11.w.5":"sepatu","ko-g12-u11.w.6":"topi","ko-g12-u11.w.7":"sarung tangan","ko-g12-u11.w.8":"piyama","ko-g12-u11.s.0":"Aku memakai baju.","ko-g12-u11.s.1":"Aku memakai kaus kaki.","ko-g12-u11.s.2":"Aku memakai topi.","ko-g12-u11.s.3":"Sepatuku kekecilan.","ko-g12-u11.s.4":"Sarung tangannya hangat.","ko-g12-u11.s.5":"Piyamanya bagus.","ko-g12-u12.title":"Cuaca","ko-g12-u12.tip":'Dalam bahasa Korea, hujan dan salju "datang": 비가 와요, 눈이 와요. Korea punya empat musim yang jelas — kamu suka musim apa?',"ko-g12-u12.w.0":"cuaca","ko-g12-u12.w.1":"matahari","ko-g12-u12.w.2":"hujan","ko-g12-u12.w.3":"salju","ko-g12-u12.w.4":"angin","ko-g12-u12.w.5":"awan","ko-g12-u12.w.6":"musim semi","ko-g12-u12.w.7":"musim panas","ko-g12-u12.w.8":"musim gugur","ko-g12-u12.w.9":"musim dingin","ko-g12-u12.s.0":"Cuacanya bagus.","ko-g12-u12.s.1":"Hujan turun.","ko-g12-u12.s.2":"Salju turun.","ko-g12-u12.s.3":"Angin bertiup.","ko-g12-u12.s.4":"Musim panas itu panas.","ko-g12-u12.s.5":"Musim dingin itu dingin.","ko-g12-u12.s.6":"Bunga mekar di musim semi.","ko-g12-u13.title":"Hari dan waktu","ko-g12-u13.tip":"Semua nama hari berakhiran 요일 (hari dalam seminggu). 토요일 dan 일요일 adalah akhir pekan — hore!","ko-g12-u13.w.0":"Senin","ko-g12-u13.w.1":"Jumat","ko-g12-u13.w.2":"Sabtu","ko-g12-u13.w.3":"Minggu","ko-g12-u13.w.4":"hari ini","ko-g12-u13.w.5":"besok","ko-g12-u13.w.6":"kemarin","ko-g12-u13.w.7":"pagi","ko-g12-u13.w.8":"malam","ko-g12-u13.s.0":"Hari ini hari Senin.","ko-g12-u13.s.1":"Besok hari Sabtu.","ko-g12-u13.s.2":"Aku istirahat pada hari Minggu.","ko-g12-u13.s.3":"Aku bangun di pagi hari.","ko-g12-u13.s.4":"Aku tidur di malam hari.","ko-g12-u13.s.5":"Aku suka hari Jumat.","ko-g12-u14.title":"Kendaraan","ko-g12-u14.tip":'Dalam bahasa Korea, semua kendaraan "dinaiki" dengan kata kerja yang sama: 버스를 타요, 자전거를 타요, 비행기를 타요.',"ko-g12-u14.w.0":"bus","ko-g12-u14.w.1":"kereta bawah tanah","ko-g12-u14.w.2":"taksi","ko-g12-u14.w.3":"kereta api","ko-g12-u14.w.4":"pesawat","ko-g12-u14.w.5":"sepeda","ko-g12-u14.w.6":"kapal","ko-g12-u14.w.7":"mobil","ko-g12-u14.w.8":"jalan","ko-g12-u14.s.0":"Aku naik bus.","ko-g12-u14.s.1":"Kereta bawah tanah itu cepat.","ko-g12-u14.s.2":"Aku naik sepeda.","ko-g12-u14.s.3":"Pesawatnya terbang.","ko-g12-u14.s.4":"Keretanya panjang.","ko-g12-u14.s.5":"Jalannya macet.","ko-g12-u15.title":"Mainan dan bermain","ko-g12-u15.tip":'Saat main petak umpet, anak-anak Korea menghitung lalu berseru 꼭꼭 숨어라, 머리카락 보일라 — "Sembunyi yang baik, rambutmu kelihatan!"',"ko-g12-u15.w.0":"mainan","ko-g12-u15.w.1":"boneka","ko-g12-u15.w.2":"balok mainan","ko-g12-u15.w.3":"bola","ko-g12-u15.w.4":"skuter","ko-g12-u15.w.5":"puzzle","ko-g12-u15.w.6":"balon","ko-g12-u15.w.7":"permainan","ko-g12-u15.w.8":"petak umpet","ko-g12-u15.s.0":"Ayo main bersama!","ko-g12-u15.s.1":"Aku melempar bola.","ko-g12-u15.s.2":"Aku naik skuter.","ko-g12-u15.s.3":"Aku membangun rumah dari balok.","ko-g12-u15.s.4":"Balonnya terbang menjauh.","ko-g12-u15.s.5":"Ayo main petak umpet.","ko-g12-u16.title":"Alam","ko-g12-u16.tip":"Sebagian besar Korea tertutup gunung, jadi mendaki gunung (등산) adalah kegiatan akhir pekan favorit keluarga.","ko-g12-u16.w.0":"gunung","ko-g12-u16.w.1":"laut","ko-g12-u16.w.2":"sungai","ko-g12-u16.w.3":"langit","ko-g12-u16.w.4":"bunga","ko-g12-u16.w.5":"pohon","ko-g12-u16.w.6":"rumput","ko-g12-u16.w.7":"pasir","ko-g12-u16.w.8":"bintang","ko-g12-u16.s.0":"Gunungnya tinggi.","ko-g12-u16.s.1":"Lautnya luas.","ko-g12-u16.s.2":"Langitnya cerah.","ko-g12-u16.s.3":"Bunganya cantik.","ko-g12-u16.s.4":"Pohonnya besar.","ko-g12-u16.s.5":"Ada banyak bintang di langit malam.","ko-g12-u17.title":"Perasaan","ko-g12-u17.tip":'Dalam bahasa Korea, kata perasaan bekerja seperti kata kerja: 기뻐요 sudah berarti "(aku) senang". Kalau ada yang kelihatan sedih, tanyakan 괜찮아요?',"ko-g12-u17.w.0":"senang","ko-g12-u17.w.1":"sedih","ko-g12-u17.w.2":"marah","ko-g12-u17.w.3":"takut","ko-g12-u17.w.4":"lelah","ko-g12-u17.w.5":"bersemangat","ko-g12-u17.w.6":"bosan","ko-g12-u17.w.7":"baik-baik saja","ko-g12-u17.s.0":"Aku senang.","ko-g12-u17.s.1":"Temanku sedih.","ko-g12-u17.s.2":"Aku capek sekali.","ko-g12-u17.s.3":"Hari ini seru sekali!","ko-g12-u17.s.4":"Kamu benar-benar baik-baik saja?","ko-g12-u17.s.5":"Ya, aku baik-baik saja.","ko-g12-u18.title":"Gerakan","ko-g12-u18.tip":'Kata yang berakhiran 요 itu sopan. 가요 bisa berarti "aku pergi", "kamu pergi", atau "ayo pergi" — situasinya yang memberi tahu!',"ko-g12-u18.w.0":"pergi","ko-g12-u18.w.1":"datang","ko-g12-u18.w.2":"makan","ko-g12-u18.w.3":"minum","ko-g12-u18.w.4":"tidur","ko-g12-u18.w.5":"berlari","ko-g12-u18.w.6":"membaca","ko-g12-u18.w.7":"melihat","ko-g12-u18.w.8":"duduk","ko-g12-u18.s.0":"Aku minum air.","ko-g12-u18.s.1":"Aku membaca buku.","ko-g12-u18.s.2":"Lari yang cepat!","ko-g12-u18.s.3":"Duduk di sini.","ko-g12-u18.s.4":"Lihat langit.","ko-g12-u18.s.5":"Aku pulang ke rumah.","ko-g12-u19.title":"Lingkungan kita","ko-g12-u19.tip":"Banyak nama tempat berakhiran 원, 관, atau 국 — 병원, 도서관, 우체국. Asalnya dari aksara Tionghoa kuno untuk bangunan.","ko-g12-u19.w.0":"lingkungan","ko-g12-u19.w.1":"toko","ko-g12-u19.w.2":"rumah sakit","ko-g12-u19.w.3":"taman","ko-g12-u19.w.4":"perpustakaan","ko-g12-u19.w.5":"toko roti","ko-g12-u19.w.6":"kantor pos","ko-g12-u19.w.7":"taman bermain","ko-g12-u19.w.8":"kantor polisi","ko-g12-u19.s.0":"Aku pergi ke taman.","ko-g12-u19.s.1":"Toko rotinya dekat.","ko-g12-u19.s.2":"Aku membaca buku di perpustakaan.","ko-g12-u19.s.3":"Aku bermain di taman bermain.","ko-g12-u19.s.4":"Rumah sakitnya di mana?","ko-g12-u19.s.5":"Tokonya besar.","ko-g12-u20.title":"Pesta ulang tahun","ko-g12-u20.tip":'Saat ulang tahun, orang Korea makan 미역국 (sup rumput laut) — para ibu memakannya setelah melahirkan, jadi artinya "terima kasih, Ibu".',"ko-g12-u20.w.0":"ulang tahun","ko-g12-u20.w.1":"pesta","ko-g12-u20.w.2":"hadiah","ko-g12-u20.w.3":"kue tar","ko-g12-u20.w.4":"lilin","ko-g12-u20.w.5":"lagu","ko-g12-u20.w.6":"kartu ucapan","ko-g12-u20.w.7":"sup rumput laut","ko-g12-u20.w.8":"selamat","ko-g12-u20.s.0":"Selamat ulang tahun!","ko-g12-u20.s.1":"Terima kasih atas hadiahnya.","ko-g12-u20.s.2":"Kue tarnya enak.","ko-g12-u20.s.3":"Aku meniup lilin.","ko-g12-u20.s.4":"Kami menyanyikan lagu.","ko-g12-u20.s.5":"Aku makan sup rumput laut."},n={"ko-g34-u01.title":"Aku …: memperkenalkan diri","ko-g34-u01.tip":"Lihat blok terakhir katanya: 학생 berakhir dengan ㅇ, jadi 학생이에요. 의사 tidak punya huruf bawah, jadi 의사예요.","ko-g34-u01.w.0":"murid","ko-g34-u01.w.1":"dokter","ko-g34-u01.w.2":"koki","ko-g34-u01.w.3":"penyanyi","ko-g34-u01.w.4":"polisi","ko-g34-u01.w.5":"nama","ko-g34-u01.w.6":"negara","ko-g34-u01.w.7":"orang","ko-g34-u01.w.8":"Korea","ko-g34-u01.w.9":"saya (sopan)","ko-g34-u01.s.0":"Aku murid SD.","ko-g34-u01.s.1":"Namaku Minjun.","ko-g34-u01.s.2":"Aku orang Amerika.","ko-g34-u01.s.3":"Ayahku seorang dokter.","ko-g34-u01.s.4":"Orang ini temanku.","ko-g34-u01.s.5":"Umurku sepuluh tahun.","ko-g34-u01.s.6":"Gurunya orang Korea.","ko-g34-u01.s.7":"Senang bertemu denganmu.","ko-g34-u01.g.title":"Mengatakan siapa dirimu: 이에요 / 예요","ko-g34-u01.g.x.0":'Untuk berkata "A adalah B", taruh 이에요 atau 예요 tepat sesudah B: 저는 학생이에요 (Saya murid).',"ko-g34-u01.g.x.1":"Kalau B berakhir dengan huruf bawah (batchim), pakai 이에요: 학생이에요. Kalau tidak, pakai 예요: 의사예요.","ko-g34-u01.g.x.2":'저 artinya "saya" saat berbicara sopan, dan 제 artinya "milik saya": 제 이름은 지우예요.',"ko-g34-u01.g.0":"Saya murid.","ko-g34-u01.g.1":"Saya dokter.","ko-g34-u01.g.2":"Nama saya Seoyeon.","ko-g34-u01.g.3":"Saya penyanyi.","ko-g34-u01.g.4":"Saya orang Korea.","ko-g34-u01.g.5":"Saya koki.","ko-g34-u01.g.5.task":"Ganti 학생 dengan 요리사 (koki).","ko-g34-u01.g.6":"Ibu saya polisi.","ko-g34-u01.g.6.task":"Ganti 의사 dengan 경찰 (polisi).","ko-g34-u01.g.7":"Teman saya orang Kanada.","ko-g34-u01.g.7.task":"Mulai dengan 제 친구는 (teman saya).","ko-g34-u01.st.title":"Teman baru","ko-g34-u01.st.l.0":"Halo! Aku Minjun.","ko-g34-u01.st.l.1":"Hai! Aku Emma.","ko-g34-u01.st.l.2":"Emma, kamu dari negara mana?","ko-g34-u01.st.l.3":"Aku orang Inggris.","ko-g34-u01.st.l.4":"Senang bertemu denganmu!","ko-g34-u01.st.l.5":"Aku juga senang bertemu denganmu.","ko-g34-u01.st.q.0":"Emma berasal dari mana?","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"Siapa nama anak laki-laki itu?","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"Ini apa?","ko-g34-u02.tip":"Tunjuk sambil bicara! 이거 ada di tanganmu, 그거 ada di tangan temanmu, dan 저거 jauh dari kalian berdua.","ko-g34-u02.w.0":"dompet","ko-g34-u02.w.1":"kacamata","ko-g34-u02.w.2":"kunci","ko-g34-u02.w.3":"ponsel","ko-g34-u02.w.4":"foto","ko-g34-u02.w.5":"benda","ko-g34-u02.w.6":"ini (benda)","ko-g34-u02.w.7":"itu (dekatmu)","ko-g34-u02.w.8":"itu (di sana)","ko-g34-u02.w.9":"apa","ko-g34-u02.s.0":"Itu yang di dekatmu apa?","ko-g34-u02.s.1":"Ini dompetku.","ko-g34-u02.s.2":"Itu yang di dekatmu kacamata?","ko-g34-u02.s.3":"Ya, itu kacamata.","ko-g34-u02.s.4":"Yang di sana itu punya siapa?","ko-g34-u02.s.5":"Itu ponsel Bu Guru.","ko-g34-u02.s.6":"Kacamata ini punya Kakek.","ko-g34-u02.s.7":"Dompet yang di sana itu punya siapa?","ko-g34-u02.g.title":"Ini, itu, itu di sana: 이 / 그 / 저","ko-g34-u02.g.x.0":"이 = ini (dekat aku), 그 = itu (dekat kamu), 저 = itu di sana (jauh dari kita berdua).","ko-g34-u02.g.x.1":'Tambahkan 거 untuk arti "benda": 이거 (benda ini), 그거, 저거. Atau tambahkan kata benda: 이 사진 (foto ini), 저 가방 (tas di sana itu).',"ko-g34-u02.g.x.2":"Bertanya dengan 뭐예요: 이거 뭐예요? — Ini apa?","ko-g34-u02.g.0":"Ini apa?","ko-g34-u02.g.1":"Yang di sana itu tasku.","ko-g34-u02.g.2":"Foto ini bagus.","ko-g34-u02.g.3":"Tolong berikan kunci itu.","ko-g34-u02.g.4":"Yang di dekatmu itu ponselku.","ko-g34-u02.g.5":"Ini pensil.","ko-g34-u02.g.5.task":"Ganti 그거 dengan 이거 (ini).","ko-g34-u02.g.6":"Yang di sana itu apa?","ko-g34-u02.g.6.task":"Tanyakan benda yang jauh: pakai 저거.","ko-g34-u02.g.7":"Kacamata ini bagus.","ko-g34-u02.g.7.task":"Ganti 저 dengan 이 (ini).","ko-g34-u03.title":"Aku punya, ada","ko-g34-u03.tip":'Satu kata yang praktis: 없어요 saja bisa berarti "aku tidak punya" atau "tidak ada". 문제 없어요! = Tidak masalah!',"ko-g34-u03.w.0":"uang","ko-g34-u03.w.1":"waktu","ko-g34-u03.w.2":"saudara kandung","ko-g34-u03.w.3":"hewan peliharaan","ko-g34-u03.w.4":"masalah","ko-g34-u03.w.5":"janji (bertemu)","ko-g34-u03.w.6":"tempat duduk","ko-g34-u03.w.7":"permen","ko-g34-u03.w.8":"pilek","ko-g34-u03.w.9":"tiket","ko-g34-u03.s.0":"Aku punya adik.","ko-g34-u03.s.1":"Ada sedikit uang di dompetku.","ko-g34-u03.s.2":"Kamu ada waktu hari ini?","ko-g34-u03.s.3":"Ada kucing di rumah.","ko-g34-u03.s.4":"Tidak masalah.","ko-g34-u03.s.5":"Besok aku ada janji.","ko-g34-u03.s.6":"Tempat duduk ini ada orangnya?","ko-g34-u03.s.7":"Ada satu permen.","ko-g34-u03.g.title":"Punya / ada: 있어요 · 없어요","ko-g34-u03.g.x.0":'있어요 artinya "ada" atau "aku punya". 없어요 artinya "tidak ada" atau "aku tidak punya".',"ko-g34-u03.g.x.1":"Taruh 이 atau 가 sesudah bendanya: 이 sesudah huruf bawah (돈이), 가 kalau tidak ada huruf bawah (사과가).","ko-g34-u03.g.x.2":"Untuk bertanya, naikkan suaramu di akhir: 시간 있어요? — Kamu ada waktu?","ko-g34-u03.g.0":"Aku tidak punya uang.","ko-g34-u03.g.1":"Ada apel.","ko-g34-u03.g.2":"Kamu punya kucing?","ko-g34-u03.g.3":"Aku tidak punya waktu.","ko-g34-u03.g.4":"Aku ada janji.","ko-g34-u03.g.5":"Aku tidak punya saudara kandung.","ko-g34-u03.g.5.task":'Ubah jadi "tidak punya": pakai 없어요.',"ko-g34-u03.g.6":"Ini tiketnya.","ko-g34-u03.g.6.task":"Ganti 사탕 dengan 표 (tiket). Perhatikan 이/가!","ko-g34-u03.g.7":"Kamu punya hewan peliharaan?","ko-g34-u03.g.7.task":"Jadikan kalimat tanya.","ko-g34-u04.title":"Kalau aku: 은 / 는","ko-g34-u04.tip":"Di Korea, anak-anak memanggil kakaknya dengan sebutan ini, bukan dengan nama. Anak laki-laki bilang 형 dan 누나; anak perempuan bilang 오빠 dan 언니.","ko-g34-u04.w.0":"kakak laki-laki (kata anak laki-laki)","ko-g34-u04.w.1":"kakak laki-laki (kata anak perempuan)","ko-g34-u04.w.2":"kakak perempuan (kata anak laki-laki)","ko-g34-u04.w.3":"kakak perempuan (kata anak perempuan)","ko-g34-u04.w.4":"tinggi badan","ko-g34-u04.w.5":"rambut","ko-g34-u04.w.6":"hobi","ko-g34-u04.w.7":"olahraga","ko-g34-u04.w.8":"musik","ko-g34-u04.w.9":"sifat","ko-g34-u04.s.0":"Kakak laki-lakiku berumur dua belas tahun.","ko-g34-u04.s.1":"Kakak perempuanku sifatnya baik.","ko-g34-u04.s.2":"Aku pendek.","ko-g34-u04.s.3":"Hobi kakak perempuanku menyanyi.","ko-g34-u04.s.4":"Rambut kakak laki-lakiku pendek.","ko-g34-u04.s.5":"Aku suka musik.","ko-g34-u04.s.6":"Kakak laki-lakiku berolahraga setiap hari.","ko-g34-u04.s.7":"Kucing banyak tidur.","ko-g34-u04.g.title":"Membicarakan topik: 은 / 는","ko-g34-u04.g.x.0":"은/는 menandai hal yang sedang kamu bicarakan (topik): 저는 학생이에요 — Kalau saya, saya murid.","ko-g34-u04.g.x.1":"Pakai 은 sesudah huruf bawah (형은) dan 는 kalau tidak ada huruf bawah (저는, 누나는).","ko-g34-u04.g.x.2":"Ini juga menunjukkan perbandingan: 형은 커요. 저는 작아요. — Kakakku tinggi, tapi aku pendek.","ko-g34-u04.g.0":"Aku Jiwoo.","ko-g34-u04.g.1":"Kakak laki-lakiku tinggi.","ko-g34-u04.g.2":"Kakak perempuanku suka musik.","ko-g34-u04.g.3":"Kucing itu lucu.","ko-g34-u04.g.4":"Hobiku menggambar.","ko-g34-u04.g.5":"Rambut kakak perempuanku panjang.","ko-g34-u04.g.5.task":"Ceritakan tentang kakak perempuanmu (언니).","ko-g34-u04.g.6":"Adikku pendek.","ko-g34-u04.g.6.task":"Ganti 형 dengan 동생. Perhatikan 은/는!","ko-g34-u04.g.7":"Kakak laki-lakiku jago olahraga.","ko-g34-u04.g.7.task":"Ceritakan tentang kakak laki-lakimu (오빠).","ko-g34-u05.title":"Kata kerja: akhiran 요","ko-g34-u05.tip":"요 di akhir membuat kalimat jadi sopan. Pakai dengan orang dewasa dan orang yang baru kamu kenal — dengan 요, kamu tidak akan salah!","ko-g34-u05.w.0":"membeli","ko-g34-u05.w.1":"bertemu","ko-g34-u05.w.2":"belajar","ko-g34-u05.w.3":"bermain","ko-g34-u05.w.4":"mendengarkan","ko-g34-u05.w.5":"menulis","ko-g34-u05.w.6":"bekerja","ko-g34-u05.w.7":"menunggu","ko-g34-u05.w.8":"mempelajari","ko-g34-u05.w.9":"bagus, baik","ko-g34-u05.s.0":"Aku belajar bahasa Korea.","ko-g34-u05.s.1":"Aku bertemu temanku di taman.","ko-g34-u05.s.2":"Aku membeli roti.","ko-g34-u05.s.3":"Adikku sedang bermain.","ko-g34-u05.s.4":"Aku mendengarkan musik.","ko-g34-u05.s.5":"Ibu sedang menunggu.","ko-g34-u05.s.6":"Ayah sedang bekerja.","ko-g34-u05.s.7":"Ayo belajar bersama.","ko-g34-u05.g.title":"Akhiran kata kerja sopan: -아요 / -어요 / 해요","ko-g34-u05.g.x.0":"Akhiran kata kerja Korea bisa berubah. Buang 다 lalu tambahkan akhiran 요: 가다 → 가요, 먹다 → 먹어요.","ko-g34-u05.g.x.1":"Kalau vokal terakhirnya ㅏ atau ㅗ, tambahkan 아요: 놀다 → 놀아요, 보다 → 봐요. Vokal lain ditambah 어요: 먹다 → 먹어요.","ko-g34-u05.g.x.2":"Kata kerja berakhiran 하다 menjadi 해요: 공부하다 → 공부해요.","ko-g34-u05.g.x.3":"Beberapa vokal bergabung: 기다리다 → 기다려요, 마시다 → 마셔요.","ko-g34-u05.g.0":"Aku bertemu temanku.","ko-g34-u05.g.1":"Aku makan nasi.","ko-g34-u05.g.2":"Aku bermain di taman bermain.","ko-g34-u05.g.3":"Aku belajar bahasa Korea.","ko-g34-u05.g.4":"Aku membaca buku.","ko-g34-u05.g.5":"Aku membeli roti.","ko-g34-u05.g.5.task":"Ubah 사다 ke bentuk sopan 요.","ko-g34-u05.g.6":"Adikku sedang menunggu.","ko-g34-u05.g.6.task":"Ubah 기다리다 ke bentuk sopan 요.","ko-g34-u05.g.7":"Ayah bekerja di perusahaan.","ko-g34-u05.g.7.task":"Ubah 일하다 ke bentuk sopan 요.","ko-g34-u05.st.title":"Hari Sabtu kamu ngapain?","ko-g34-u05.st.l.0":"Hari Sabtu kamu ngapain?","ko-g34-u05.st.l.1":"Aku belajar berenang.","ko-g34-u05.st.l.2":"Wah! Aku main sepak bola.","ko-g34-u05.st.l.3":"Kalau hari Minggu?","ko-g34-u05.st.l.4":"Aku pergi ke rumah nenek. Kami makan bersama.","ko-g34-u05.st.l.5":"Asyik! Aku istirahat di rumah.","ko-g34-u05.st.q.0":"Seoyeon belajar apa pada hari Sabtu?","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"Minjun pergi ke mana pada hari Minggu?","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"Yang kamu makan, tonton, dan lakukan: 을 / 를","ko-g34-u06.tip":"Ingat urutannya: siapa → apa → melakukan. 저는 (aku) 피자를 (piza) 먹어요 (makan). Kata kerjanya selalu paling akhir!","ko-g34-u06.w.0":"film","ko-g34-u06.w.1":"gambar, lukisan","ko-g34-u06.w.2":"surat","ko-g34-u06.w.3":"koran","ko-g34-u06.w.4":"piano","ko-g34-u06.w.5":"sepak bola","ko-g34-u06.w.6":"renang","ko-g34-u06.w.7":"bersih-bersih","ko-g34-u06.w.8":"mencuci piring","ko-g34-u06.w.9":"kopi","ko-g34-u06.s.0":"Aku menonton film bersama adikku.","ko-g34-u06.s.1":"Aku menggambar.","ko-g34-u06.s.2":"Aku menulis surat untuk temanku.","ko-g34-u06.s.3":"Aku bermain piano.","ko-g34-u06.s.4":"Aku bermain sepak bola.","ko-g34-u06.s.5":"Ayah mencuci piring.","ko-g34-u06.s.6":"Ibu minum kopi.","ko-g34-u06.s.7":"Aku membersihkan kamarku.","ko-g34-u06.g.title":"Benda yang dikenai: 을 / 를","ko-g34-u06.g.x.0":"을/를 menandai objek — benda yang kamu makan, tonton, atau lakukan: 사과를 먹어요 (Aku makan apel).","ko-g34-u06.g.x.1":"Pakai 을 sesudah huruf bawah (빵을) dan 를 kalau tidak ada huruf bawah (커피를).","ko-g34-u06.g.x.2":"Bahasa Korea menaruh kata kerja paling akhir: 저는 영화를 봐요 = aku · film · menonton.","ko-g34-u06.g.0":"Aku menonton film.","ko-g34-u06.g.1":"Aku makan roti.","ko-g34-u06.g.2":"Aku minum kopi.","ko-g34-u06.g.3":"Aku menulis surat.","ko-g34-u06.g.4":"Aku membaca koran.","ko-g34-u06.g.5":"Aku bermain piano.","ko-g34-u06.g.5.task":"Taruh kata kerjanya di akhir.","ko-g34-u06.g.6":"Adikku menggambar.","ko-g34-u06.g.6.task":"Taruh kata kerjanya di akhir.","ko-g34-u06.g.7":"Kakak laki-lakiku berenang.","ko-g34-u06.g.7.task":"Ganti 축구 (sepak bola) dengan 수영 (renang).","ko-g34-u07.title":"Tidak: 안","ko-g34-u07.tip":"Kalau kamu tidak suka makanan pedas, kalimat ini berguna di Korea: 안 매운 거 있어요? — Ada yang tidak pedas?","ko-g34-u07.w.0":"pedas","ko-g34-u07.w.1":"mahal","ko-g34-u07.w.2":"murah","ko-g34-u07.w.3":"sulit","ko-g34-u07.w.4":"mudah","ko-g34-u07.w.5":"sibuk","ko-g34-u07.w.6":"panas (cuaca)","ko-g34-u07.w.7":"sakit","ko-g34-u07.w.8":"enak","ko-g34-u07.w.9":"seru","ko-g34-u07.s.0":"Tteokbokki agak pedas.","ko-g34-u07.s.1":"Soal ini tidak mudah.","ko-g34-u07.s.2":"Buku ini tidak mahal.","ko-g34-u07.s.3":"Ayah minum kopi.","ko-g34-u07.s.4":"PR-nya tidak sulit.","ko-g34-u07.s.5":"Hari ini tidak panas.","ko-g34-u07.s.6":"Sudah tidak sakit lagi.","ko-g34-u07.s.7":"Filmnya seru sekali.","ko-g34-u07.g.title":"Tidak: 안 + kata kerja","ko-g34-u07.g.x.0":'Taruh 안 tepat di depan kata kerja atau kata sifat untuk berkata "tidak": 매워요 → 안 매워요.',"ko-g34-u07.g.x.1":"Pada kata kerja 해요, 안 diletakkan tepat sebelum 해요: 공부해요 → 공부 안 해요.","ko-g34-u07.g.x.2":"맛있어요 dan 재미있어요 punya lawan katanya sendiri: 맛없어요, 재미없어요.","ko-g34-u07.g.0":"Kimchinya tidak pedas.","ko-g34-u07.g.1":"Aku tidak minum kopi.","ko-g34-u07.g.2":"Hari ini aku tidak sibuk.","ko-g34-u07.g.3":"Aku tidak mengerjakan PR.","ko-g34-u07.g.4":"Piza ini tidak enak.","ko-g34-u07.g.5":"Aku tidak bermain piano.","ko-g34-u07.g.5.task":"Jadikan kalimat negatif dengan 안.","ko-g34-u07.g.6":"Hari ini tidak dingin.","ko-g34-u07.g.6.task":"Jadikan kalimat negatif dengan 안.","ko-g34-u07.g.7":"Kakak laki-lakiku tidak berolahraga.","ko-g34-u07.g.7.task":"Jadikan kalimat negatif. 안 diletakkan tepat sebelum 해요.","ko-g34-u08.title":"Pergi ke suatu tempat: 에 가요","ko-g34-u08.tip":"Busan adalah kota besar Korea di tepi laut, dan Pulau Jeju (제주도) adalah tempat favorit untuk liburan keluarga.","ko-g34-u08.w.0":"pasar","ko-g34-u08.w.1":"supermarket","ko-g34-u08.w.2":"kolam renang","ko-g34-u08.w.3":"bioskop","ko-g34-u08.w.4":"museum","ko-g34-u08.w.5":"kebun binatang","ko-g34-u08.w.6":"perusahaan, kantor","ko-g34-u08.w.7":"Seoul","ko-g34-u08.w.8":"perjalanan","ko-g34-u08.w.9":"akhir pekan","ko-g34-u08.s.0":"Akhir pekan ini aku pergi ke kebun binatang.","ko-g34-u08.s.1":"Ibu pergi ke pasar.","ko-g34-u08.s.2":"Ayah pergi ke kantor.","ko-g34-u08.s.3":"Di musim panas aku pergi ke kolam renang.","ko-g34-u08.s.4":"Besok kamu mau ke mana?","ko-g34-u08.s.5":"Aku pergi ke museum.","ko-g34-u08.s.6":"Besok aku pergi ke Seoul.","ko-g34-u08.s.7":"Ayo pergi ke bioskop bersama!","ko-g34-u08.g.title":"Pergi ke suatu tempat: 에 가요 · 에 와요","ko-g34-u08.g.x.0":"Taruh 에 sesudah nama tempat untuk mengatakan tujuanmu: 학교에 가요 (Aku pergi ke sekolah).","ko-g34-u08.g.x.1":"에 tetap sama sesudah kata apa pun, ada huruf bawah atau tidak: 시장에, 마트에.","ko-g34-u08.g.x.2":'Bertanya dengan 어디: 어디에 가요? — Kamu mau ke mana? Untuk "datang", pakai 와요: 집에 와요.',"ko-g34-u08.g.0":"Aku pergi ke sekolah.","ko-g34-u08.g.1":"Aku pergi ke kebun binatang.","ko-g34-u08.g.2":"Kamu mau ke mana?","ko-g34-u08.g.3":"Temanku datang ke rumahku.","ko-g34-u08.g.4":"Kami pergi ke kolam renang.","ko-g34-u08.g.5":"Besok aku pergi ke museum.","ko-g34-u08.g.5.task":"Ganti 극장 (bioskop) dengan 박물관 (museum).","ko-g34-u08.g.6":"Ibu pergi ke pasar.","ko-g34-u08.g.6.task":"Ganti 마트 dengan 시장 (pasar).","ko-g34-u08.g.7":"Temanku datang ke rumah kami.","ko-g34-u08.g.7.task":"Ganti 가요 (pergi) dengan 와요 (datang).","ko-g34-u08.st.title":"Rencana akhir pekan","ko-g34-u08.st.l.0":"Akhir pekan ini kamu mau ke mana?","ko-g34-u08.st.l.1":"Aku mau ke kebun binatang. Di sana ada panda!","ko-g34-u08.st.l.2":"Wah, asyik! Kamu pergi dengan siapa?","ko-g34-u08.st.l.3":"Dengan ayah dan adikku. Kalau kamu, Jiwoo?","ko-g34-u08.st.l.4":"Aku mau ke rumah nenek. Nenek tinggal di Busan.","ko-g34-u08.st.l.5":"Laut di Busan indah sekali!","ko-g34-u08.st.q.0":"Hajun pergi ke mana?","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"Nenek Jiwoo tinggal di mana?","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"Di mana?","ko-g34-u09.tip":"Main petak umpet dengan mainan: sembunyikan, lalu beri petunjuk dalam bahasa Korea — 의자 아래에 있어요! 책상 위에 있어요!","ko-g34-u09.w.0":"di atas","ko-g34-u09.w.1":"di bawah","ko-g34-u09.w.2":"di samping","ko-g34-u09.w.3":"di depan","ko-g34-u09.w.4":"di belakang","ko-g34-u09.w.5":"di dalam","ko-g34-u09.w.6":"di luar","ko-g34-u09.w.7":"di sini","ko-g34-u09.w.8":"di situ (dekatmu)","ko-g34-u09.w.9":"di sana","ko-g34-u09.s.0":"Kucingnya di atas tempat tidur.","ko-g34-u09.s.1":"Kucingnya di bawah sofa.","ko-g34-u09.s.2":"Pensilnya di dalam tas.","ko-g34-u09.s.3":"Ada taman di depan rumah kami.","ko-g34-u09.s.4":"Ibu duduk di sampingku.","ko-g34-u09.s.5":"Anak anjingnya di belakang pintu.","ko-g34-u09.s.6":"Toiletnya di sana.","ko-g34-u09.s.7":"Ibu di luar.","ko-g34-u09.g.title":"Letak benda: 에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"Pakai 에 있어요 untuk mengatakan letak sesuatu: 고양이가 방에 있어요 (Kucingnya di kamar).","ko-g34-u09.g.x.1":"Untuk tempat yang tepat, sebut bendanya dulu, lalu posisinya, lalu 에: 책상 위에 (di atas meja), 의자 아래에 (di bawah kursi).","ko-g34-u09.g.x.2":"Posisi: 위 di atas, 아래 di bawah, 옆 di samping, 앞 di depan, 뒤 di belakang, 안 di dalam, 밖 di luar.","ko-g34-u09.g.0":"Bukunya di atas meja.","ko-g34-u09.g.1":"Bolanya di bawah kursi.","ko-g34-u09.g.2":"Kucingnya di dalam kotak.","ko-g34-u09.g.3":"Temanku di sampingku.","ko-g34-u09.g.4":"Ada anak anjing di belakang pohon.","ko-g34-u09.g.5":"Susunya di dalam kulkas.","ko-g34-u09.g.5.task":"Taruh susu di dalam kulkas: pakai 안.","ko-g34-u09.g.6":"Tamannya di depan sekolah.","ko-g34-u09.g.6.task":"Pindahkan taman ke depan sekolah: pakai 앞.","ko-g34-u09.g.7":"Sepatunya di samping pintu?","ko-g34-u09.g.7.task":"Jadikan kalimat tanya.","ko-g34-u10.title":"Tempat melakukannya: 에서","ko-g34-u10.tip":"에 dipakai untuk pergi ke atau berada di suatu tempat (학교에 가요). 에서 dipakai untuk melakukan sesuatu di sana (학교에서 공부해요).","ko-g34-u10.w.0":"halaman sekolah","ko-g34-u10.w.1":"restoran","ko-g34-u10.w.2":"kafe","ko-g34-u10.w.3":"pantai","ko-g34-u10.w.4":"gedung olahraga","ko-g34-u10.w.5":"bola basket","ko-g34-u10.w.6":"menggambar","ko-g34-u10.w.7":"beristirahat","ko-g34-u10.w.8":"mengambil (foto)","ko-g34-u10.w.9":"menyanyi","ko-g34-u10.s.0":"Aku bermain di halaman sekolah.","ko-g34-u10.s.1":"Aku makan mi dingin di restoran.","ko-g34-u10.s.2":"Aku membaca buku di perpustakaan.","ko-g34-u10.s.3":"Aku membuat istana pasir di pantai.","ko-g34-u10.s.4":"Aku beristirahat di rumah.","ko-g34-u10.s.5":"Aku menggambar di taman.","ko-g34-u10.s.6":"Aku lompat tali di gedung olahraga.","ko-g34-u10.s.7":"Kita ketemu di mana?","ko-g34-u10.g.title":"Tempat terjadinya kegiatan: 에서","ko-g34-u10.g.x.0":"Pakai 에서 sesudah tempat kamu melakukan sesuatu: 식당에서 먹어요 (Aku makan di restoran).","ko-g34-u10.g.x.1":"Pakai 에 dengan 가요, 와요, dan 있어요: 식당에 가요, 식당에 있어요.","ko-g34-u10.g.x.2":"Tes cepat: kalau ada yang melakukan kegiatan di sana, pakai 에서.","ko-g34-u10.g.0":"Aku makan di restoran.","ko-g34-u10.g.1":"Aku bermain sepak bola di halaman sekolah.","ko-g34-u10.g.2":"Aku minum jus di kafe.","ko-g34-u10.g.3":"Aku pergi ke perpustakaan.","ko-g34-u10.g.4":"Kakak laki-lakiku ada di kamarnya.","ko-g34-u10.g.5":"Aku memotret di pantai.","ko-g34-u10.g.5.task":"Ganti 공원 (taman) dengan 바닷가 (pantai).","ko-g34-u10.g.6":"Aku bermain di rumah bersama temanku.","ko-g34-u10.g.6.task":'Ubah jadi "bermain di rumah": pakai 에서 dan 놀아요.',"ko-g34-u10.g.7":"Aku bermain basket di gedung olahraga.","ko-g34-u10.g.7.task":"Katakan apa yang kamu lakukan di sana: 농구를 해요 (bermain basket).","ko-g34-u11.title":"Menghitung benda","ko-g34-u11.tip":"Untuk uang dipakai kelompok angka yang lain (천 = 1.000): 삼천 원 artinya 3.000 won. Untuk menghitung benda dipakai 한, 두, 세, 네.","ko-g34-u11.w.0":"satu (sebelum kata penggolong)","ko-g34-u11.w.1":"dua (sebelum kata penggolong)","ko-g34-u11.w.2":"tiga (sebelum kata penggolong)","ko-g34-u11.w.3":"empat (sebelum kata penggolong)","ko-g34-u11.w.4":"orang (kata penggolong)","ko-g34-u11.w.5":"ekor (kata penggolong)","ko-g34-u11.w.6":"buku (kata penggolong)","ko-g34-u11.w.7":"lembar (kata penggolong)","ko-g34-u11.w.8":"tahun umur (kata penggolong)","ko-g34-u11.w.9":"berapa","ko-g34-u11.s.0":"Satu apel, ya.","ko-g34-u11.s.1":"Keluargaku ada empat orang.","ko-g34-u11.s.2":"Ada dua ekor kucing.","ko-g34-u11.s.3":"Umurmu berapa?","ko-g34-u11.s.4":"Umurku sembilan tahun.","ko-g34-u11.s.5":"Aku membaca tiga buku.","ko-g34-u11.s.6":"Selembar kertas, ya.","ko-g34-u11.s.7":"Ada sepuluh murid.","ko-g34-u11.g.title":"Menghitung: angka + kata penggolong","ko-g34-u11.g.x.0":"Bahasa Korea memakai kata penggolong sesudah angka: 사과 두 개 (dua buah apel), 학생 세 명 (tiga orang murid).","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 menjadi lebih pendek sebelum kata penggolong: 한, 두, 세, 네.","ko-g34-u11.g.x.2":"Kata penggolong: 개 benda, 명 orang, 마리 hewan, 권 buku, 장 lembar kertas, 살 tahun umur.","ko-g34-u11.g.0":"Dua apel, ya.","ko-g34-u11.g.1":"Ada tiga murid.","ko-g34-u11.g.2":"Ada seekor anak anjing.","ko-g34-u11.g.3":"Umurku delapan tahun.","ko-g34-u11.g.4":"Ada empat buku.","ko-g34-u11.g.5":"Ada tiga ekor kucing.","ko-g34-u11.g.5.task":"Ubah jadi tiga ekor kucing.","ko-g34-u11.g.6":"Dua lembar kertas, ya.","ko-g34-u11.g.6.task":"Minta dua lembar.","ko-g34-u11.g.7":"Empat teman akan datang.","ko-g34-u11.g.7.task":"Ubah jadi empat teman.","ko-g34-u11.st.title":"Di toko roti","ko-g34-u11.st.l.0":"Halo! Dua roti, ya.","ko-g34-u11.st.l.1":"Roti yang mana?","ko-g34-u11.st.l.2":"Satu roti krim yang ini dan satu roti cokelat yang di sana.","ko-g34-u11.st.l.3":"Ini dia. Semuanya 3.000 won.","ko-g34-u11.st.l.4":"Susunya satu juga, ya.","ko-g34-u11.st.l.5":"Baik, jadi totalnya 4.000 won.","ko-g34-u11.st.q.0":"Berapa roti yang dibeli Seoyeon?","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"Apa lagi yang dia beli?","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"Jam berapa sekarang?","ko-g34-u12.tip":"Jam memakai 한, 두, 세 (angka untuk menghitung), tetapi menit memakai 일, 이, 삼 (angka yang lain). Jadi 3:10 adalah 세 시 십 분.","ko-g34-u12.w.0":"jam (pukul)","ko-g34-u12.w.1":"menit","ko-g34-u12.w.2":"setengah (lewat)","ko-g34-u12.w.3":"sekarang","ko-g34-u12.w.4":"pagi (a.m.)","ko-g34-u12.w.5":"siang/sore (p.m.)","ko-g34-u12.w.6":"makan siang","ko-g34-u12.w.7":"malam, makan malam","ko-g34-u12.w.8":"awal, pagi-pagi","ko-g34-u12.w.9":"terlambat, larut","ko-g34-u12.s.0":"Sekarang jam berapa?","ko-g34-u12.s.1":"Jam satu.","ko-g34-u12.s.2":"Ayo ketemu jam setengah tiga.","ko-g34-u12.s.3":"Aku berangkat sekolah jam delapan pagi.","ko-g34-u12.s.4":"Aku makan siang jam satu.","ko-g34-u12.s.5":"Ayo ketemu jam empat sore.","ko-g34-u12.s.6":"Aku mengerjakan PR pada malam hari.","ko-g34-u12.s.7":"Hari ini aku tidur larut.","ko-g34-u12.g.title":"Menyebut waktu: 몇 시예요?","ko-g34-u12.g.x.0":"Sebut jamnya dengan angka hitungan yang pendek + 시: 한 시, 두 시, 세 시, 열두 시.","ko-g34-u12.g.x.1":"Setengah adalah 반: 두 시 반 (2:30). Menit memakai kelompok angka yang lain: 오 분, 십 분.","ko-g34-u12.g.x.2":'Tambahkan 에 untuk "pada jam": 일곱 시에 일어나요 (Aku bangun jam tujuh).',"ko-g34-u12.g.0":"Sekarang jam satu.","ko-g34-u12.g.1":"Jam setengah empat.","ko-g34-u12.g.2":"Aku bangun jam tujuh.","ko-g34-u12.g.3":"Aku makan siang jam dua belas.","ko-g34-u12.g.4":"Kita ketemu jam berapa?","ko-g34-u12.g.5":"Aku pulang jam empat.","ko-g34-u12.g.5.task":"Ganti waktunya jadi jam empat.","ko-g34-u12.g.6":"Jam setengah enam.","ko-g34-u12.g.6.task":"Tambahkan setengah jam: pakai 반.","ko-g34-u12.g.7":"Aku tidur jam sembilan.","ko-g34-u12.g.7.task":"Katakan kamu tidur jam sembilan: pakai 에 dan 자요.","ko-g34-u13.title":"Siapa? Di mana? Kapan? Kenapa?","ko-g34-u13.tip":"Pertanyaan paling berguna di toko Korea: 이거 얼마예요? (Ini berapa?) Coba tanyakan di toko-tokoan di rumah!","ko-g34-u13.w.0":"siapa","ko-g34-u13.w.1":"di mana","ko-g34-u13.w.2":"kapan","ko-g34-u13.w.3":"kenapa","ko-g34-u13.w.4":"bagaimana","ko-g34-u13.w.5":"jenis apa","ko-g34-u13.w.6":"berapa (harga)","ko-g34-u13.w.7":"yang mana","ko-g34-u13.w.8":"alasan","ko-g34-u13.w.9":"jawaban","ko-g34-u13.s.0":"Orang itu siapa?","ko-g34-u13.s.1":"Liburannya kapan?","ko-g34-u13.s.2":"Kenapa kamu sedih?","ko-g34-u13.s.3":"Bagaimana cara ke perpustakaan?","ko-g34-u13.s.4":"Ini berapa?","ko-g34-u13.s.5":"Kamu suka makanan apa?","ko-g34-u13.s.6":"Kamu dari negara mana?","ko-g34-u13.s.7":"Toiletnya di mana?","ko-g34-u13.g.title":"Kata tanya: 누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 siapa · 뭐 apa · 어디 di mana · 언제 kapan · 왜 kenapa · 어떻게 bagaimana · 얼마 berapa (harga).","ko-g34-u13.g.x.1":"Dengan 이에요/예요, kata tanya ada di akhir: 누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"Dengan kata kerja lain, kata tanya ada sebelum kata kerja: 어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"Orang ini siapa?","ko-g34-u13.g.1":"Ulang tahunmu kapan?","ko-g34-u13.g.2":"Kenapa kamu menangis?","ko-g34-u13.g.3":"Apel ini berapa?","ko-g34-u13.g.4":"Kamu ke sekolah naik apa?","ko-g34-u13.g.5":"Kamu mau ke mana?","ko-g34-u13.g.5.task":'Tanyakan "ke mana": pakai 어디에.',"ko-g34-u13.g.6":"Kamu datang kapan?","ko-g34-u13.g.6.task":'Tanyakan "kapan": pakai 언제.',"ko-g34-u13.g.7":"Orang itu siapa?","ko-g34-u13.g.7.task":'Tanyakan "siapa": pakai 누구예요.',"ko-g34-u14.title":"Aku ingin …","ko-g34-u14.tip":"KAMU ingin melakukan apa? Buat tiga kalimat dengan -고 싶어요 tentang akhir pekan ini.","ko-g34-u14.w.0":"cita-cita","ko-g34-u14.w.1":"ilmuwan","ko-g34-u14.w.2":"pelukis","ko-g34-u14.w.3":"atlet, pemain","ko-g34-u14.w.4":"luar angkasa","ko-g34-u14.w.5":"taman hiburan","ko-g34-u14.w.6":"tteokbokki (kue beras pedas)","ko-g34-u14.w.7":"memelihara (hewan, tanaman)","ko-g34-u14.w.8":"terbang","ko-g34-u14.w.9":"manusia salju","ko-g34-u14.s.0":"Aku ingin menjadi ilmuwan.","ko-g34-u14.s.1":"Aku ingin pergi ke luar angkasa.","ko-g34-u14.s.2":"Aku ingin makan tteokbokki.","ko-g34-u14.s.3":"Aku ingin memelihara kucing.","ko-g34-u14.s.4":"Aku ingin pergi ke taman hiburan.","ko-g34-u14.s.5":"Akhir pekan ini kamu ingin melakukan apa?","ko-g34-u14.s.6":"Hari ini aku ingin istirahat.","ko-g34-u14.s.7":"Cita-citaku menjadi pelukis.","ko-g34-u14.g.title":"Ingin melakukan sesuatu: -고 싶어요","ko-g34-u14.g.x.0":"Untuk mengatakan kamu ingin melakukan sesuatu, buang 다 lalu tambahkan 고 싶어요: 먹다 → 먹고 싶어요 (Aku ingin makan).","ko-g34-u14.g.x.1":"Caranya sama untuk semua kata kerja, ada huruf bawah atau tidak: 가고 싶어요, 놀고 싶어요, 쉬고 싶어요.","ko-g34-u14.g.x.2":'"Ingin menjadi" adalah 되고 싶어요: 의사가 되고 싶어요 (Aku ingin menjadi dokter).',"ko-g34-u14.g.0":"Aku ingin makan piza.","ko-g34-u14.g.1":"Aku ingin pergi ke laut.","ko-g34-u14.g.2":"Aku ingin menjadi pelukis.","ko-g34-u14.g.3":"Aku ingin bermain dengan temanku.","ko-g34-u14.g.4":"Kamu ingin melakukan apa?","ko-g34-u14.g.5":"Aku ingin pergi ke luar angkasa.","ko-g34-u14.g.5.task":"Katakan keinginanmu: pakai -고 싶어요.","ko-g34-u14.g.6":"Aku ingin memelihara anak anjing.","ko-g34-u14.g.6.task":"Katakan keinginanmu: pakai -고 싶어요.","ko-g34-u14.g.7":"Aku ingin membuat manusia salju.","ko-g34-u14.g.7.task":"Katakan keinginanmu: pakai -고 싶어요.","ko-g34-u14.st.title":"Cita-citaku","ko-g34-u14.st.l.0":"Anak-anak, apa cita-cita kalian?","ko-g34-u14.st.l.1":"Aku ingin menjadi pemain sepak bola!","ko-g34-u14.st.l.2":"Aku ingin menjadi ilmuwan. Aku ingin pergi ke luar angkasa.","ko-g34-u14.st.l.3":"Aku ingin menjadi pelukis.","ko-g34-u14.st.l.4":"Semuanya cita-cita yang hebat!","ko-g34-u14.st.q.0":"Seoyeon ingin menjadi apa?","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"Siapa yang ingin menjadi pelukis?","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"Suka dan tidak suka","ko-g34-u15.tip":'Buat daftar "suka / tidak suka" bersama keluargamu: 아빠는 커피를 좋아해요. 저는 벌레를 싫어해요!',"ko-g34-u15.w.0":"suka","ko-g34-u15.w.1":"tidak suka","ko-g34-u15.w.2":"wortel","ko-g34-u15.w.3":"sayuran","ko-g34-u15.w.4":"cabai","ko-g34-u15.w.5":"cokelat","ko-g34-u15.w.6":"dongeng","ko-g34-u15.w.7":"kartun, komik","ko-g34-u15.w.8":"serangga","ko-g34-u15.w.9":"paling","ko-g34-u15.s.0":"Aku suka cokelat.","ko-g34-u15.s.1":"Ayah suka wortel.","ko-g34-u15.s.2":"Kamu suka dongeng apa?","ko-g34-u15.s.3":"Kakak perempuanku takut serangga.","ko-g34-u15.s.4":"Kakak laki-lakiku suka dongeng.","ko-g34-u15.s.5":"Aku paling suka semangka.","ko-g34-u15.s.6":"Aku juga suka sayuran.","ko-g34-u15.s.7":"Cabainya terlalu pedas.","ko-g34-u15.g.title":"Suka dan tidak suka: 좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"Pakai 을/를 좋아해요 untuk hal yang kamu suka: 사과를 좋아해요.","ko-g34-u15.g.x.1":"Pakai 을/를 싫어해요 untuk hal yang tidak kamu suka: 벌레를 싫어해요.","ko-g34-u15.g.x.2":'좋아요 juga berarti "aku suka": 이 노래가 좋아요. Dengan 좋아요, pakai 이/가, bukan 을/를.',"ko-g34-u15.g.0":"Aku suka kucing.","ko-g34-u15.g.1":"Adikku benci wortel.","ko-g34-u15.g.2":"Aku suka cokelat.","ko-g34-u15.g.3":"Aku suka lagu ini.","ko-g34-u15.g.4":"Kamu suka kartun apa?","ko-g34-u15.g.5":"Aku tidak suka serangga.","ko-g34-u15.g.5.task":"Katakan kamu tidak suka.","ko-g34-u15.g.6":"Kakak laki-lakiku suka sayuran.","ko-g34-u15.g.6.task":"Ganti 고기 (daging) dengan 채소 (sayuran).","ko-g34-u15.g.7":"Aku paling suka stroberi.","ko-g34-u15.g.7.task":'Katakan "paling": tambahkan 제일.',"ko-g34-u16.title":"Kemarin aku …: kalimat lampau","ko-g34-u16.tip":'Dengarkan bunyi ㅆ pada kalimat lampau: 갔어요, 봤어요, 했어요. ㅆ itu seperti kata "sudah" kecil!',"ko-g34-u16.w.0":"minggu lalu","ko-g34-u16.w.1":"tadi","ko-g34-u16.w.2":"sudah melakukan","ko-g34-u16.w.3":"sudah pergi","ko-g34-u16.w.4":"sudah makan","ko-g34-u16.w.5":"sudah melihat, menonton","ko-g34-u16.w.6":"sudah datang","ko-g34-u16.w.7":"sudah tidur","ko-g34-u16.w.8":"tadi seru","ko-g34-u16.w.9":"liburan sekolah","ko-g34-u16.s.0":"Kemarin aku menonton film.","ko-g34-u16.s.1":"Tadi pagi aku makan roti.","ko-g34-u16.s.2":"Minggu lalu aku pergi ke Busan.","ko-g34-u16.s.3":"Aku sudah menyelesaikan semua PR-ku.","ko-g34-u16.s.4":"Temanku datang ke rumahku.","ko-g34-u16.s.5":"Tadi malam aku tidur cepat.","ko-g34-u16.s.6":"Liburannya seru sekali.","ko-g34-u16.s.7":"Tadi aku bertemu Ibu.","ko-g34-u16.g.title":"Kalimat lampau: -았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"Untuk masa lampau, ubah akhiran 요: 가요 → 갔어요, 먹어요 → 먹었어요.","ko-g34-u16.g.x.1":"Kata kerja yang vokal terakhirnya ㅏ atau ㅗ ditambah 았어요 (놀다 → 놀았어요, 보다 → 봤어요). Kata kerja lain ditambah 었어요 (먹다 → 먹었어요).","ko-g34-u16.g.x.2":"Kata kerja 하다 menjadi 했어요: 공부하다 → 공부했어요.","ko-g34-u16.g.0":"Kemarin aku pergi ke taman.","ko-g34-u16.g.1":"Aku sudah sarapan.","ko-g34-u16.g.2":"Aku menonton film.","ko-g34-u16.g.3":"Aku mengerjakan PR.","ko-g34-u16.g.4":"Aku bermain dengan temanku.","ko-g34-u16.g.5":"Aku membaca buku.","ko-g34-u16.g.5.task":"Ubah ke bentuk lampau.","ko-g34-u16.g.6":"Adikku tidur cepat.","ko-g34-u16.g.6.task":"Ubah ke bentuk lampau.","ko-g34-u16.g.7":"Ayah memasak.","ko-g34-u16.g.7.task":"Ubah ke bentuk lampau.","ko-g34-u16.st.title":"Bagaimana liburanmu?","ko-g34-u16.st.l.0":"Liburanmu menyenangkan?","ko-g34-u16.st.l.1":"Ya! Aku pergi ke Pulau Jeju.","ko-g34-u16.st.l.2":"Wah, kamu ngapain di Jeju?","ko-g34-u16.st.l.3":"Aku berenang di laut. Aku juga makan banyak jeruk.","ko-g34-u16.st.l.4":"Aku menginap di rumah nenek. Aku bermain dengan anak anjing.","ko-g34-u16.st.l.5":"Liburannya seru sekali!","ko-g34-u16.st.q.0":"Hajun pergi ke mana?","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"Jiwoo bermain dengan apa?","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"Aku akan …: kalimat masa depan","ko-g34-u17.tip":"Lampau, sekarang, masa depan: 갔어요 (sudah pergi) → 가요 (pergi) → 갈 거예요 (akan pergi). Ucapkan ketiganya untuk 먹다 dan 하다!","ko-g34-u17.w.0":"minggu depan","ko-g34-u17.w.1":"tahun depan","ko-g34-u17.w.2":"rencana","ko-g34-u17.w.3":"ujian","ko-g34-u17.w.4":"berkemah","ko-g34-u17.w.5":"tenda","ko-g34-u17.w.6":"latihan","ko-g34-u17.w.7":"pindah rumah","ko-g34-u17.w.8":"mungkin","ko-g34-u17.w.9":"sebentar lagi","ko-g34-u17.s.0":"Besok aku akan pergi berkemah.","ko-g34-u17.s.1":"Akhir pekan ini aku akan berlatih piano.","ko-g34-u17.s.2":"Sepertinya akan hujan.","ko-g34-u17.s.3":"Minggu depan ada ujian.","ko-g34-u17.s.4":"Aku akan tidur di tenda.","ko-g34-u17.s.5":"Sebentar lagi kita akan makan malam.","ko-g34-u17.s.6":"Tahun depan umurku sepuluh tahun.","ko-g34-u17.s.7":"Saat liburan kamu akan ngapain?","ko-g34-u17.g.title":"Masa depan: -(으)ㄹ 거예요","ko-g34-u17.g.x.0":"Untuk membicarakan masa depan, buang 다 lalu tambahkan ㄹ 거예요: 가다 → 갈 거예요, 하다 → 할 거예요.","ko-g34-u17.g.x.1":"Kalau akar katanya berakhir dengan huruf bawah, tambahkan 을 거예요: 먹다 → 먹을 거예요, 읽다 → 읽을 거예요.","ko-g34-u17.g.x.2":'Ini juga bisa berarti "mungkin": 비가 올 거예요 (Sepertinya akan hujan).',"ko-g34-u17.g.0":"Besok aku akan pergi ke taman.","ko-g34-u17.g.1":"Aku akan makan piza untuk makan malam.","ko-g34-u17.g.2":"Akhir pekan ini aku akan belajar.","ko-g34-u17.g.3":"Sepertinya akan turun salju.","ko-g34-u17.g.4":"Aku akan membaca buku.","ko-g34-u17.g.5":"Besok aku akan bertemu temanku.","ko-g34-u17.g.5.task":"Ubah jadi besok: pakai 내일 dan -ㄹ 거예요.","ko-g34-u17.g.6":"Aku akan pergi berkemah.","ko-g34-u17.g.6.task":"Ubah ke bentuk masa depan.","ko-g34-u17.g.7":"Saat liburan aku akan belajar berenang.","ko-g34-u17.g.7.task":"Ubah ke bentuk masa depan.","ko-g34-u18.title":"Dan, dengan, juga","ko-g34-u18.tip":"Ceritakan rutinitas pagimu dalam satu rantai panjang: 일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"bangun","ko-g34-u18.w.1":"mandi, cuci muka","ko-g34-u18.w.2":"memakai (baju)","ko-g34-u18.w.3":"menyikat gigi","ko-g34-u18.w.4":"merapikan","ko-g34-u18.w.5":"mandi pancuran","ko-g34-u18.w.6":"dan (lalu)","ko-g34-u18.w.7":"dan, dengan","ko-g34-u18.w.8":"juga","ko-g34-u18.w.9":"bersama-sama","ko-g34-u18.s.0":"Aku bangun lalu cuci muka.","ko-g34-u18.s.1":"Aku cuci tangan lalu makan.","ko-g34-u18.s.2":"Aku punya susu dan apel.","ko-g34-u18.s.3":"Aku juga ikut pergi bersama.","ko-g34-u18.s.4":"Aku memakai kaus kaki lalu keluar.","ko-g34-u18.s.5":"Aku merapikan kamar lalu istirahat.","ko-g34-u18.s.6":"Aku pergi ke taman dengan Ayah.","ko-g34-u18.s.7":"Aku membaca buku lalu tidur.","ko-g34-u18.g.title":"Dan: -고 · 하고 · 도","ko-g34-u18.g.x.0":"Untuk menggabungkan dua kegiatan, buang 다 lalu tambahkan 고: 먹다 → 먹고. 밥을 먹고 양치해요 (Aku makan lalu menyikat gigi).","ko-g34-u18.g.x.1":'Untuk menggabungkan dua kata benda, pakai 하고: 빵하고 우유 (roti dan susu). 하고 juga berarti "dengan": 엄마하고 가요.',"ko-g34-u18.g.x.2":'도 berarti "juga" dan menggantikan 은/는, 이/가, atau 을/를: 저도 좋아요 (Aku juga suka).',"ko-g34-u18.g.0":"Aku makan lalu menyikat gigi.","ko-g34-u18.g.1":"Aku berpakaian lalu pergi ke sekolah.","ko-g34-u18.g.2":"Aku makan roti dan susu.","ko-g34-u18.g.3":"Aku juga ingin pergi.","ko-g34-u18.g.4":"Aku pergi ke pasar dengan Ibu.","ko-g34-u18.g.5":"Aku mengerjakan PR lalu bermain.","ko-g34-u18.g.5.task":"Gabungkan dua kalimat dengan -고.","ko-g34-u18.g.6":"Aku mandi lalu tidur.","ko-g34-u18.g.6.task":"Gabungkan dua kalimat dengan -고.","ko-g34-u18.g.7":"Adikku juga datang.","ko-g34-u18.g.7.task":'Katakan "juga": pakai 도.',"ko-g34-u19.title":"Tolong …","ko-g34-u19.tip":"Dua kalimat ajaib untuk di Korea: 주세요 (tolong berikan) dan 천천히 말해 주세요 (tolong bicara pelan-pelan). Ucapkan sambil tersenyum!","ko-g34-u19.w.0":"tolong berikan","ko-g34-u19.w.1":"tolong (melunakkan permintaan)","ko-g34-u19.w.2":"silakan duduk","ko-g34-u19.w.3":"silakan datang","ko-g34-u19.w.4":"tolong tunggu","ko-g34-u19.w.5":"dengan tenang","ko-g34-u19.w.6":"pelan-pelan","ko-g34-u19.w.7":"lagi","ko-g34-u19.w.8":"sebentar","ko-g34-u19.w.9":"tolong bantu aku","ko-g34-u19.s.0":"Segelas susu, ya.","ko-g34-u19.s.1":"Silakan duduk.","ko-g34-u19.s.2":"Selamat datang, silakan masuk.","ko-g34-u19.s.3":"Tolong tunggu di sini.","ko-g34-u19.s.4":"Tolong jalan sedikit lebih pelan.","ko-g34-u19.s.5":"Tolong ulangi sekali lagi.","ko-g34-u19.s.6":"Tolong tenang di perpustakaan.","ko-g34-u19.s.7":"Tolong bantu aku!","ko-g34-u19.g.title":"Meminta: -(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"Untuk meminta seseorang melakukan sesuatu dengan sopan, buang 다 lalu tambahkan 세요: 가다 → 가세요, 오다 → 오세요.","ko-g34-u19.g.x.1":"Kalau akar katanya berakhir dengan huruf bawah, tambahkan 으세요: 앉다 → 앉으세요, 읽다 → 읽으세요.","ko-g34-u19.g.x.2":"Untuk meminta tolong bagi dirimu, pakai -아/어 주세요: 도와주세요 (tolong bantu aku), 말해 주세요 (tolong beri tahu aku).","ko-g34-u19.g.0":"Silakan duduk di sini.","ko-g34-u19.g.1":"Silakan lewat sini.","ko-g34-u19.g.2":"Tolong baca buku ini.","ko-g34-u19.g.3":"Tolong bicara pelan-pelan.","ko-g34-u19.g.4":"Air, ya.","ko-g34-u19.g.5":"Tolong tunggu sebentar.","ko-g34-u19.g.5.task":"Jadikan permintaan sopan: pakai -세요.","ko-g34-u19.g.6":"Tolong cuci tanganmu.","ko-g34-u19.g.6.task":"Jadikan permintaan sopan: pakai -으세요.","ko-g34-u19.g.7":"Tolong ulangi lagi.","ko-g34-u19.g.7.task":"Minta tolong: pakai 주세요.","ko-g34-u19.st.title":"Di restoran","ko-g34-u19.st.l.0":"Selamat datang! Berapa orang?","ko-g34-u19.st.l.1":"Tiga orang.","ko-g34-u19.st.l.2":"Silakan lewat sini. Silakan duduk di sini.","ko-g34-u19.st.l.3":"Satu bibimbap dan dua gimbap, ya.","ko-g34-u19.st.l.4":"Baik, mohon tunggu sebentar.","ko-g34-u19.st.l.5":"Airnya juga, ya!","ko-g34-u19.st.q.0":"Ada berapa orang dalam keluarga itu?","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"Apa yang dipesan Seoyeon?","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"Sangat, sedikit, terlalu","ko-g34-u20.tip":"Main lawan kata: satu orang bilang 커요!, yang lain menjawab 작아요! Lalu coba 빨라요 → 느려요.","ko-g34-u20.w.0":"besar","ko-g34-u20.w.1":"kecil","ko-g34-u20.w.2":"panjang","ko-g34-u20.w.3":"pendek","ko-g34-u20.w.4":"berat","ko-g34-u20.w.5":"ringan","ko-g34-u20.w.6":"cepat","ko-g34-u20.w.7":"lambat","ko-g34-u20.w.8":"sangat","ko-g34-u20.w.9":"terlalu","ko-g34-u20.s.0":"Paus sangat besar.","ko-g34-u20.s.1":"Tikus sangat kecil.","ko-g34-u20.s.2":"Buku ini agak berat.","ko-g34-u20.s.3":"Kura-kura sangat lambat.","ko-g34-u20.s.4":"Keretanya terlalu cepat.","ko-g34-u20.s.5":"Balon itu ringan.","ko-g34-u20.s.6":"Rambut adikku panjang.","ko-g34-u20.s.7":"Pensil ini terlalu pendek.","ko-g34-u20.g.title":"Sangat, sedikit, terlalu: 아주 · 조금 · 너무","ko-g34-u20.g.x.0":"Kata sifat Korea sudah bekerja seperti kata kerja: 커요 (besar), 빨라요 (cepat).","ko-g34-u20.g.x.1":"Taruh 아주 (sangat), 조금 (sedikit), atau 너무 (terlalu) tepat di depannya: 아주 커요, 조금 작아요, 너무 무거워요.","ko-g34-u20.g.x.2":"Pelajari berpasangan: 커요 ↔ 작아요, 길어요 ↔ 짧아요, 빨라요 ↔ 느려요, 무거워요 ↔ 가벼워요.","ko-g34-u20.g.0":"Gajah sangat besar.","ko-g34-u20.g.1":"Tasnya terlalu berat.","ko-g34-u20.g.2":"Siput itu lambat.","ko-g34-u20.g.3":"Rambutku agak pendek.","ko-g34-u20.g.4":"Cheetah sangat cepat.","ko-g34-u20.g.5":"Celana ini terlalu panjang.","ko-g34-u20.g.5.task":'Katakan "terlalu panjang": tambahkan 너무.',"ko-g34-u20.g.6":"Semut sangat kecil.","ko-g34-u20.g.6.task":"Ubah jadi kebalikannya.","ko-g34-u20.g.7":"Bulu burung sangat ringan.","ko-g34-u20.g.7.task":'Katakan "sangat ringan": tambahkan 아주.'},g={"ko-g56-u01.title":"Sekarang: -고 있어요","ko-g56-u01.tip":"Lihat sekelilingmu dan ceritakan apa yang semua orang sedang lakukan: 아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"akhir-akhir ini","ko-g56-u01.w.1":"gitar","ko-g56-u01.w.2":"panggilan telepon","ko-g56-u01.w.3":"bersiap-siap","ko-g56-u01.w.4":"jalan-jalan","ko-g56-u01.w.5":"tidur siang","ko-g56-u01.w.6":"cucian","ko-g56-u01.w.7":"pesan teks","ko-g56-u01.w.8":"mengirim","ko-g56-u01.w.9":"mencari","ko-g56-u01.w.10":"membuat","ko-g56-u01.w.11":"tertawa, tersenyum","ko-g56-u01.s.0":"Kamu sedang apa sekarang?","ko-g56-u01.s.1":"Adikku sedang tidur siang.","ko-g56-u01.s.2":"Ibu sedang menelepon.","ko-g56-u01.s.3":"Akhir-akhir ini aku sedang belajar gitar.","ko-g56-u01.s.4":"Ayah sedang mencuci baju.","ko-g56-u01.s.5":"Kakak laki-lakiku sedang menelepon temannya.","ko-g56-u01.s.6":"Nenek sedang jalan-jalan dengan anak anjing.","ko-g56-u01.s.7":"Aku sedang bersiap-siap ke sekolah.","ko-g56-u01.g.title":"Sedang terjadi sekarang: -고 있어요","ko-g56-u01.g.x.0":"Untuk mengatakan sesuatu sedang terjadi sekarang, buang 다 lalu tambahkan 고 있어요: 먹다 → 먹고 있어요 (Aku sedang makan).","ko-g56-u01.g.x.1":"Ini juga dipakai untuk hal yang sedang kamu lakukan akhir-akhir ini: 요즘 기타를 배우고 있어요.","ko-g56-u01.g.x.2":"Untuk masa lampau, pakai 고 있었어요: 그때 자고 있었어요 (Waktu itu aku sedang tidur).","ko-g56-u01.g.0":"Aku sedang makan sekarang.","ko-g56-u01.g.1":"Bayinya sedang tidur siang.","ko-g56-u01.g.2":"Kakak laki-lakiku sedang bermain gitar.","ko-g56-u01.g.3":"Kamu sedang apa?","ko-g56-u01.g.4":"Waktu itu aku sedang membaca buku.","ko-g56-u01.g.5":"Ibu sedang mencuci baju.","ko-g56-u01.g.5.task":"Katakan itu sedang terjadi sekarang: pakai -고 있어요.","ko-g56-u01.g.6":"Aku sedang mengirim pesan ke temanku.","ko-g56-u01.g.6.task":"Katakan itu sedang terjadi sekarang: pakai -고 있어요.","ko-g56-u01.g.7":"Akhir-akhir ini aku sedang belajar berenang.","ko-g56-u01.g.7.task":"Katakan kamu sedang melakukannya akhir-akhir ini: pakai -고 있어요.","ko-g56-u02.title":"Bisa dan tidak bisa","ko-g56-u02.tip":"Kamu sedang membaca Hangul sekarang — huruf yang dibuat Raja Sejong supaya semua orang bisa membaca. Keren, kan!","ko-g56-u02.w.0":"Hangul (abjad Korea)","ko-g56-u02.w.1":"huruf, aksara","ko-g56-u02.w.2":"bunyi","ko-g56-u02.w.3":"bentuk","ko-g56-u02.w.4":"raja","ko-g56-u02.w.5":"rakyat jelata (kata kuno)","ko-g56-u02.w.6":"dengan mudah","ko-g56-u02.w.7":"menyetir","ko-g56-u02.w.8":"siulan","ko-g56-u02.w.9":"bahasa asing","ko-g56-u02.w.10":"sudah membuat","ko-g56-u02.w.11":"pintar","ko-g56-u02.s.0":"Adikku sudah bisa sedikit membaca Hangul.","ko-g56-u02.s.1":"Adikku belum bisa naik sepeda.","ko-g56-u02.s.2":"Ibu tidak bisa menyetir.","ko-g56-u02.s.3":"Kakak laki-lakiku pandai bersiul.","ko-g56-u02.s.4":"Hujan turun, jadi aku tidak bisa main di luar.","ko-g56-u02.s.5":"Kakak laki-lakiku bisa berbicara dua bahasa asing.","ko-g56-u02.s.6":"Kamu bisa belajar Hangul dengan mudah.","ko-g56-u02.s.7":"Kamu bisa membaca huruf ini dengan mudah.","ko-g56-u02.g.title":"Bisa dan tidak bisa: -(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"Untuk mengatakan kamu bisa melakukan sesuatu, buang 다 lalu tambahkan ㄹ 수 있어요: 가다 → 갈 수 있어요, 하다 → 할 수 있어요.","ko-g56-u02.g.x.1":"Sesudah huruf bawah, tambahkan 을 수 있어요: 읽다 → 읽을 수 있어요. Akar kata yang berakhiran ㄹ tetap sama: 놀다 → 놀 수 있어요.","ko-g56-u02.g.x.2":'Untuk "tidak bisa", ganti 있어요 dengan 없어요: 갈 수 없어요. Kamu juga bisa menaruh 못 sebelum kata kerja: 못 가요.',"ko-g56-u02.g.0":"Aku bisa membaca Hangul.","ko-g56-u02.g.1":"Ayah bisa menyetir.","ko-g56-u02.g.2":"Hari ini aku tidak bisa bermain.","ko-g56-u02.g.3":"Kamu bisa bersiul?","ko-g56-u02.g.4":"Aku tidak bisa berenang.","ko-g56-u02.g.5":"Adikku tidak bisa naik sepeda.","ko-g56-u02.g.5.task":'Ubah jadi "tidak bisa": pakai 없어요.',"ko-g56-u02.g.6":"Kakak laki-lakiku bisa berbicara bahasa asing.","ko-g56-u02.g.6.task":"Katakan dia bisa: pakai -ㄹ 수 있어요.","ko-g56-u02.g.7":"Kamu bisa membaca huruf ini?","ko-g56-u02.g.7.task":'Tanyakan "bisakah kamu": pakai -을 수 있어요.',"ko-g56-u02.r.ko":"Rahasia Hangul","ko-g56-u02.r.genre":"Sejarah","ko-g56-u02.r.p.0":"Dahulu kala, orang Korea menulis dengan aksara Tionghoa. Aksaranya sangat banyak dan sulit. Jadi banyak rakyat biasa tidak bisa membaca.","ko-g56-u02.r.p.1":"Raja Sejong dari Joseon sangat menyayangi rakyatnya. Maka pada tahun 1443 ia membuat huruf yang mudah. Huruf itulah Hangul.","ko-g56-u02.r.p.2":"Huruf konsonan dibuat dengan melihat bentuk mulut dan lidah saat mengucapkan setiap bunyi. Misalnya, ㄱ menunjukkan pangkal lidah yang menutup tenggorokan. Huruf vokal dibuat dari langit, bumi, dan manusia.","ko-g56-u02.r.p.3":"Dengan hanya 24 huruf, Hangul bisa menuliskan hampir semua bunyi. Jadi siapa pun bisa belajar membacanya dalam beberapa hari. Pada tanggal 9 Oktober, Hari Hangul, orang Korea merayakan huruf-huruf ini.","ko-g56-u02.r.q.3.o.0":"rakyat biasa","ko-g56-u02.r.q.3.o.1":"para raja","ko-g56-u02.r.q.3.o.2":"para guru","ko-g56-u03.title":"Harus: -아야 해요","ko-g56-u03.tip":"Anak-anak Korea belajar aturan keselamatan jalan ini: di zebra cross, berhenti, lihat ke kiri dan kanan, lalu angkat tanganmu sambil menyeberang.","ko-g56-u03.w.0":"aturan","ko-g56-u03.w.1":"menaati (aturan)","ko-g56-u03.w.2":"keselamatan","ko-g56-u03.w.3":"helm","ko-g56-u03.w.4":"menyeberang","ko-g56-u03.w.5":"lampu lalu lintas","ko-g56-u03.w.6":"zebra cross","ko-g56-u03.w.7":"barisan, antrean","ko-g56-u03.w.8":"giliran","ko-g56-u03.w.9":"penting","ko-g56-u03.w.10":"dengan bersih","ko-g56-u03.w.11":"pasti, harus","ko-g56-u03.s.0":"Kamu harus mencuci tangan dengan bersih.","ko-g56-u03.s.1":"Kamu harus menyeberang di zebra cross.","ko-g56-u03.s.2":"Kamu harus memakai helm saat naik sepeda.","ko-g56-u03.s.3":"Kami mengantre di kantin.","ko-g56-u03.s.4":"Besok aku harus berangkat sekolah pagi-pagi.","ko-g56-u03.s.5":"Aku harus mengerjakan PR dulu.","ko-g56-u03.s.6":"Semua orang menaati aturan.","ko-g56-u03.s.7":"Kalau lampunya hijau, angkat tanganmu lalu menyeberang.","ko-g56-u03.g.title":"Harus: -아야 / -어야 해요","ko-g56-u03.g.x.0":"Untuk mengatakan kamu harus melakukan sesuatu, ambil bentuk 요, buang 요, lalu tambahkan 야 해요: 가요 → 가야 해요, 먹어요 → 먹어야 해요.","ko-g56-u03.g.x.1":"Kata kerja 하다 menjadi 해야 해요: 공부해야 해요 (Aku harus belajar).","ko-g56-u03.g.x.2":"Untuk masa lampau, katakan 해야 했어요: 어제 일찍 자야 했어요 (Kemarin aku harus tidur cepat).","ko-g56-u03.g.0":"Kamu harus mencuci tangan.","ko-g56-u03.g.1":"Aku harus pergi sekarang.","ko-g56-u03.g.2":"Aku harus mengerjakan PR.","ko-g56-u03.g.3":"Kamu harus mengantre.","ko-g56-u03.g.4":"Kamu harus memakai helm.","ko-g56-u03.g.5":"Besok aku harus bangun pagi.","ko-g56-u03.g.5.task":"Katakan kamu harus: pakai -아야 해요.","ko-g56-u03.g.6":"Kamu harus menaati aturan sekolah.","ko-g56-u03.g.6.task":"Katakan kamu harus: pakai -어야 해요.","ko-g56-u03.g.7":"Kemarin aku harus belajar.","ko-g56-u03.g.7.task":"Ubah jadi kemarin (bentuk lampau).","ko-g56-u04.title":"Kalau, ketika: -(으)면","ko-g56-u04.tip":'Buat kalimat "kalau" tentang harimu: 숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.',"ko-g56-u04.w.0":"empat musim","ko-g56-u04.w.1":"jelas, tegas","ko-g56-u04.w.2":"bunga sakura","ko-g56-u04.w.3":"musim hujan","ko-g56-u04.w.4":"daun musim gugur","ko-g56-u04.w.5":"perang bola salju","ko-g56-u04.w.6":"hangat","ko-g56-u04.w.7":"sejuk, segar","ko-g56-u04.w.8":"kalau, seandainya","ko-g56-u04.w.9":"mekar","ko-g56-u04.w.10":"jatuh, gugur","ko-g56-u04.w.11":"menumpuk","ko-g56-u04.s.0":"Kalau salju menumpuk, kami main kereta luncur.","ko-g56-u04.s.1":"Kalau cuacanya hangat, aku pergi ke taman.","ko-g56-u04.s.2":"Ketika musim panas datang, musim hujan dimulai.","ko-g56-u04.s.3":"Kalau kamu haus, minumlah air.","ko-g56-u04.s.4":"Ketika musim gugur datang, daun-daun berguguran.","ko-g56-u04.s.5":"Kalau tidak ada waktu, ayo kerjakan besok.","ko-g56-u04.s.6":"Kalau anginnya sejuk, aku jalan-jalan.","ko-g56-u04.s.7":"Kalau hujan, kami bermain di rumah.","ko-g56-u04.g.title":"Kalau, ketika: -(으)면","ko-g56-u04.g.x.0":'Buang 다 lalu tambahkan 면 untuk "kalau" atau "ketika": 오다 → 오면. 비가 오면 우산을 써요 (Kalau hujan, aku memakai payung).',"ko-g56-u04.g.x.1":"Sesudah huruf bawah, tambahkan 으면: 있다 → 있으면, 먹다 → 먹으면.","ko-g56-u04.g.x.2":"Akar kata yang berakhiran ㄹ cukup ditambah 면: 놀다 → 놀면, 만들다 → 만들면.","ko-g56-u04.g.0":"Kalau hujan, aku memakai payung.","ko-g56-u04.g.1":"Kalau kamu ada waktu, ayo main.","ko-g56-u04.g.2":"Kalau kamu lapar, bilang ya.","ko-g56-u04.g.3":"Kalau kamu capek, istirahatlah.","ko-g56-u04.g.4":"Kalau kamu minum obat ini, kamu akan sembuh.","ko-g56-u04.g.5":"Ketika musim semi datang, bunga sakura mekar.","ko-g56-u04.g.5.task":"Gabungkan dengan -면 (ketika).","ko-g56-u04.g.6":"Ketika salju turun, kami perang bola salju.","ko-g56-u04.g.6.task":"Gabungkan dengan -면 (ketika).","ko-g56-u04.g.7":"Kalau aku terlambat, aku akan menelepon.","ko-g56-u04.g.7.task":"Gabungkan dengan -으면 (kalau).","ko-g56-u04.r.ko":"Empat musim di Korea","ko-g56-u04.r.genre":"Budaya","ko-g56-u04.r.p.0":"Korea punya empat musim yang jelas. Musim semi, musim panas, musim gugur, dan musim dingin semuanya berbeda. Ketika musim semi datang, cuacanya hangat. Bunga sakura dan forsythia mekar di gunung dan di jalan. Orang-orang pergi ke taman untuk melihat bunga.","ko-g56-u04.r.p.1":"Musim panas sangat panas. Ketika musim hujan datang, hujan turun deras. Ketika musim hujan selesai, anak-anak pergi ke pantai atau kolam renang.","ko-g56-u04.r.p.2":"Di musim gugur anginnya sejuk. Gunung-gunung menjadi indah dengan daun merah dan kuning. Musim dingin itu dingin. Ketika salju menumpuk, anak-anak membuat manusia salju dan bermain perang bola salju.","ko-g56-u04.r.q.3.o.0":"daun musim gugur yang berwarna-warni","ko-g56-u04.r.q.3.o.1":"bunga sakura","ko-g56-u04.r.q.3.o.2":"manusia salju","ko-g56-u05.title":"Karena, jadi: -아서","ko-g56-u05.tip":'만나서 반가워요 (Senang bertemu denganmu) secara harfiah berarti "Karena kita bertemu, aku senang" — sekarang kamu bisa melihat -아서 di dalamnya!',"ko-g56-u05.w.0":"kesiangan","ko-g56-u05.w.1":"terlambat (ke sekolah)","ko-g56-u05.w.2":"demam","ko-g56-u05.w.3":"obat","ko-g56-u05.w.4":"jatuh","ko-g56-u05.w.5":"terluka","ko-g56-u05.w.6":"licin","ko-g56-u05.w.7":"senang (bertemu)","ko-g56-u05.w.8":"sudah terlambat","ko-g56-u05.w.9":"ketinggalan (bus)","ko-g56-u05.w.10":"jadi, maka","ko-g56-u05.w.11":"karena","ko-g56-u05.s.0":"Aku pilek, jadi aku tidak bisa ke sekolah.","ko-g56-u05.s.1":"Salju turun, jadi jalannya licin.","ko-g56-u05.s.2":"Aku sangat mengantuk, jadi aku tidur siang.","ko-g56-u05.s.3":"Aku terlambat, jadi aku naik taksi.","ko-g56-u05.s.4":"Aku senang bertemu temanku lagi.","ko-g56-u05.s.5":"Hujan turun, jadi aku tinggal di rumah.","ko-g56-u05.s.6":"Aku pergi ke sekolah lalu bertemu temanku.","ko-g56-u05.s.7":"Aku terluka, jadi aku mengoleskan obat.","ko-g56-u05.g.title":"Karena, jadi: -아서 / -어서","ko-g56-u05.g.x.0":"Untuk memberi alasan, ambil bentuk 요, buang 요, lalu tambahkan 서: 고파요 → 고파서. 배가 고파서 먹었어요 (Aku lapar, jadi aku makan).","ko-g56-u05.g.x.1":"Kata kerja 하다 menjadi 해서: 피곤해서, 공부해서.","ko-g56-u05.g.x.2":"Hanya kata kerja terakhir yang menunjukkan masa lampau: 늦잠을 자서 늦었어요 — jangan pernah 잤어서.","ko-g56-u05.g.x.3":"-아서/어서 juga menyambung langkah-langkah secara berurutan: 시장에 가서 과일을 샀어요 (Aku pergi ke pasar lalu membeli buah).","ko-g56-u05.g.0":"Aku lapar, jadi aku makan roti.","ko-g56-u05.g.1":"Aku kesiangan, jadi aku terlambat.","ko-g56-u05.g.2":"Aku demam, jadi aku pergi ke rumah sakit.","ko-g56-u05.g.3":"Aku sangat capek, jadi aku tidur cepat.","ko-g56-u05.g.4":"Senang bertemu denganmu.","ko-g56-u05.g.5":"Aku ketinggalan bus, jadi aku terlambat.","ko-g56-u05.g.5.task":"Gabungkan dengan -어서 (jadi).","ko-g56-u05.g.6":"Jalannya licin, jadi aku jatuh.","ko-g56-u05.g.6.task":"Gabungkan dengan -어서 (jadi).","ko-g56-u05.g.7":"Aku pergi ke pasar lalu membeli buah.","ko-g56-u05.g.7.task":"Gabungkan langkah-langkahnya dengan -아서.","ko-g56-u06.title":"Tapi: -지만","ko-g56-u06.tip":"Saat Tahun Baru Imlek, anak-anak membungkuk kepada orang yang lebih tua dan berkata 새해 복 많이 받으세요 (Semoga banyak berkah di tahun baru).","ko-g56-u06.w.0":"Tahun Baru Imlek (Seollal)","ko-g56-u06.w.1":"hari raya tradisional","ko-g56-u06.w.2":"Chuseok (festival panen)","ko-g56-u06.w.3":"sungkem Tahun Baru","ko-g56-u06.w.4":"angpao Tahun Baru","ko-g56-u06.w.5":"sup kue beras","ko-g56-u06.w.6":"hanbok (pakaian tradisional)","ko-g56-u06.w.7":"kerabat","ko-g56-u06.w.8":"berkumpul","ko-g56-u06.w.9":"menerima","ko-g56-u06.w.10":"tradisi","ko-g56-u06.w.11":"tapi, namun","ko-g56-u06.s.0":"Chuseok ada di musim gugur.","ko-g56-u06.s.1":"Tahun Baru Imlek sibuk tapi menyenangkan.","ko-g56-u06.s.2":"Di luar dingin, tapi di rumah hangat.","ko-g56-u06.s.3":"Adikku kecil tapi kuat.","ko-g56-u06.s.4":"Aku kenyang. Tapi aku ingin makan lagi.","ko-g56-u06.s.5":"Saat Tahun Baru Imlek, para kerabat berkumpul.","ko-g56-u06.s.6":"Aku memberi sungkem Tahun Baru kepada kakek.","ko-g56-u06.s.7":"Aku mendapat banyak angpao Tahun Baru.","ko-g56-u06.g.title":"Tapi: -지만 · 하지만","ko-g56-u06.g.x.0":'Untuk berkata "tapi" di dalam satu kalimat, buang 다 lalu tambahkan 지만: 맛있다 → 맛있지만. 맛있지만 뜨거워요 (Enak tapi panas).',"ko-g56-u06.g.x.1":"-지만 bekerja sama untuk semua kata kerja dan kata sifat: 춥지만, 예쁘지만, 했지만.","ko-g56-u06.g.x.2":'Untuk memulai kalimat baru dengan "tapi", pakai 하지만: 피곤해요. 하지만 행복해요.',"ko-g56-u06.g.0":"Sup kue beras enak tapi panas.","ko-g56-u06.g.1":"Dingin, tapi aku merasa senang.","ko-g56-u06.g.2":"Hanbok cantik tapi agak tidak nyaman.","ko-g56-u06.g.3":"Adikku masih kecil tapi pintar.","ko-g56-u06.g.4":"Aku capek. Tapi aku bahagia.","ko-g56-u06.g.5":"Belajar itu sulit tapi seru.","ko-g56-u06.g.5.task":"Jadikan satu kalimat dengan -지만.","ko-g56-u06.g.6":"Kemarin hujan, tapi hari ini cerah.","ko-g56-u06.g.6.task":"Jadikan satu kalimat dengan -지만.","ko-g56-u06.g.7":"Kakak laki-lakiku tinggi, tapi aku pendek.","ko-g56-u06.g.7.task":"Jadikan satu kalimat dengan -지만.","ko-g56-u06.r.ko":"Pagi Tahun Baru","ko-g56-u06.r.genre":"Budaya","ko-g56-u06.r.p.0":"Ini pagi Tahun Baru. Jiwoo bangun pagi-pagi dan memakai hanbok. Hanbok cantik tapi agak tidak nyaman. Semua kerabat berkumpul di rumah kakek.","ko-g56-u06.r.p.1":'Jiwoo memberi sungkem Tahun Baru kepada kakek dan neneknya. "Selamat Tahun Baru!" Kakek tersenyum dan memberinya angpao Tahun Baru.',"ko-g56-u06.r.p.2":"Pagi itu semua orang makan sup kue beras bersama. Di Korea, orang bilang kalau makan sup kue beras, umurmu bertambah satu tahun. Siang harinya Jiwoo bermain yunnori, sebuah permainan papan, dengan sepupu-sepupunya. Dia kalah, tapi dia sangat senang.","ko-g56-u07.title":"Lebih besar, paling besar","ko-g56-u07.tip":"Bandingkan benda-benda di sekitarmu: 아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. Siapa yang 제일 di keluargamu?","ko-g56-u07.w.0":"daripada","ko-g56-u07.w.1":"lebih","ko-g56-u07.w.2":"kurang","ko-g56-u07.w.3":"paling","ko-g56-u07.w.4":"tinggi","ko-g56-u07.w.5":"rendah","ko-g56-u07.w.6":"luas, lapang","ko-g56-u07.w.7":"sempit","ko-g56-u07.w.8":"kota","ko-g56-u07.w.9":"desa","ko-g56-u07.w.10":"sepupu","ko-g56-u07.w.11":"perbandingan","ko-g56-u07.s.0":"Ayah lebih tinggi daripada Ibu.","ko-g56-u07.s.1":"Kota lebih ramai daripada desa.","ko-g56-u07.s.2":"Kimchi ini kurang pedas dibanding kimchi itu.","ko-g56-u07.s.3":"Minjun paling cepat di kelas kami.","ko-g56-u07.s.4":"Gunung lebih tinggi daripada bukit.","ko-g56-u07.s.5":"Dari semua hewan, aku paling suka kucing.","ko-g56-u07.s.6":"Kamarku lebih kecil daripada kamar adikku.","ko-g56-u07.s.7":"Sepupuku setahun lebih tua daripada aku.","ko-g56-u07.g.title":"Membandingkan: 보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"Untuk membandingkan, taruh 보다 sesudah benda pembandingnya: 형이 저보다 커요 (Kakakku lebih tinggi daripada aku).","ko-g56-u07.g.x.1":"Kamu bisa menambahkan 더 (lebih) atau 덜 (kurang): 서울이 부산보다 더 커요.","ko-g56-u07.g.x.2":'Untuk "paling", pakai 제일 atau 가장: 제일 빨라요 (paling cepat). Tambahkan 에서 untuk kelompoknya: 우리 반에서 제일 빨라요.',"ko-g56-u07.g.0":"Kakak laki-lakiku lebih tinggi daripada aku.","ko-g56-u07.g.1":"Seoul lebih besar daripada Busan.","ko-g56-u07.g.2":"Hari ini tidak sedingin kemarin.","ko-g56-u07.g.3":"Minjun paling cepat.","ko-g56-u07.g.4":"Aku paling suka musim panas.","ko-g56-u07.g.5":"Desa lebih tenang daripada kota.","ko-g56-u07.g.5.task":"Bandingkan dengan kota: tambahkan 도시보다.","ko-g56-u07.g.6":"Jalan ini lebih lebar daripada jalan itu.","ko-g56-u07.g.6.task":"Bandingkan dengan jalan itu: tambahkan 저 길보다.","ko-g56-u07.g.7":"Jiwoo paling tinggi di kelas kami.","ko-g56-u07.g.7.task":'Katakan "paling tinggi": tambahkan 제일.',"ko-g56-u08.title":"Anak yang baik, buku yang seru","ko-g56-u08.tip":"Ceritakan hal-hal favoritmu: 제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은 …","ko-g56-u08.w.0":"baru","ko-g56-u08.w.1":"lama, bekas","ko-g56-u08.w.2":"zaman dulu","ko-g56-u08.w.3":"baik hati","ko-g56-u08.w.4":"lucu, imut","ko-g56-u08.w.5":"terkenal","ko-g56-u08.w.6":"tenang, sepi","ko-g56-u08.w.7":"berisik","ko-g56-u08.w.8":"ramah","ko-g56-u08.w.9":"membosankan","ko-g56-u08.w.10":"sama","ko-g56-u08.w.11":"berbeda","ko-g56-u08.s.0":"Nenek punya kucing yang lucu.","ko-g56-u08.s.1":"Anak yang baik hati itu membantu adiknya.","ko-g56-u08.s.2":"Aku membaca di perpustakaan yang tenang.","ko-g56-u08.s.3":"Ini restoran yang terkenal.","ko-g56-u08.s.4":"Aku suka guru yang baik hati.","ko-g56-u08.s.5":"Kartun yang ditonton kakak laki-lakiku seru.","ko-g56-u08.s.6":"Warna favoritku hijau.","ko-g56-u08.s.7":"Aku memakai sepatu baru.","ko-g56-u08.g.title":"Menerangkan kata benda: -(으)ㄴ / -는","ko-g56-u08.g.x.0":"Untuk menaruh kata sifat sebelum kata benda, buang 다 lalu tambahkan ㄴ: 착하다 → 착한 아이 (anak yang baik hati), 크다 → 큰 집.","ko-g56-u08.g.x.1":"Sesudah huruf bawah, tambahkan 은: 작다 → 작은 고양이. Kata yang berakhiran 있다/없다 ditambah 는: 재미있는 책.","ko-g56-u08.g.x.2":"Untuk kegiatan yang sedang berlangsung, tambahkan 는: 읽다 → 읽는 책 (buku yang sedang kubaca), 좋아하다 → 좋아하는 음식 (makanan favorit).","ko-g56-u08.g.0":"Dia anak yang baik hati.","ko-g56-u08.g.1":"Ada kucing kecil.","ko-g56-u08.g.2":"Aku membaca buku yang seru.","ko-g56-u08.g.3":"Makanan favoritku tteokbokki.","ko-g56-u08.g.4":"Aku belajar di perpustakaan yang tenang.","ko-g56-u08.g.5":"Aku punya anak anjing yang lucu.","ko-g56-u08.g.5.task":'Taruh "lucu" sebelum 강아지 dalam satu kalimat.',"ko-g56-u08.g.6":"Ini lagu yang terkenal.","ko-g56-u08.g.6.task":'Katakan "lagu yang terkenal": taruh 유명한 sebelum 노래.',"ko-g56-u08.g.7":"Buku yang sedang kubaca sekarang seru.","ko-g56-u08.g.7.task":"Jadikan satu kalimat: 읽는 책.","ko-g56-u09.title":"Hormat kepada orang tua","ko-g56-u09.tip":"Kakek-nenek Korea sering memanggil cucunya dengan sayang 우리 강아지 (anak anjingku). Itu panggilan yang manis!","ko-g56-u09.w.0":"rumah (orang yang lebih tua)","ko-g56-u09.w.1":"makanan (orang yang lebih tua)","ko-g56-u09.w.2":"silakan makan (kepada orang tua)","ko-g56-u09.w.3":"tidur (orang yang lebih tua)","ko-g56-u09.w.4":"berada (orang yang lebih tua)","ko-g56-u09.w.5":"kepada (orang yang lebih tua)","ko-g56-u09.w.6":"memberi (kepada orang tua)","ko-g56-u09.w.7":"umur (orang yang lebih tua)","ko-g56-u09.w.8":"perkataan (orang yang lebih tua)","ko-g56-u09.w.9":"bahasa sopan","ko-g56-u09.w.10":"orang dewasa","ko-g56-u09.w.11":"cucu","ko-g56-u09.s.0":"Kakek, silakan dimakan.","ko-g56-u09.s.1":"Bu Guru ada di kelas.","ko-g56-u09.s.2":"Kakek sedang tidur sekarang.","ko-g56-u09.s.3":"Aku memberi bunga kepada Nenek.","ko-g56-u09.s.4":"Kakek sedang membaca koran.","ko-g56-u09.s.5":"Aku mendengarkan guruku dengan baik.","ko-g56-u09.s.6":"Kita memakai bahasa sopan kepada orang dewasa.","ko-g56-u09.s.7":"Kakekmu umurnya berapa?","ko-g56-u09.g.title":"Menunjukkan rasa hormat: -(으)세요 · 께 · kata khusus","ko-g56-u09.g.x.0":"Saat membicarakan orang yang lebih tua, tambahkan 시 pada kata kerjanya: 가요 → 가세요, 웃어요 → 웃으세요 (Nenek tersenyum).","ko-g56-u09.g.x.1":"Beberapa kata berubah sama sekali: 먹어요 → 드세요, 자요 → 주무세요, 있어요 → 계세요, 집 → 댁, 나이 → 연세.","ko-g56-u09.g.x.2":'Pakai 께 untuk "kepada" orang yang lebih tua (할머니께 드려요) dan 께서 sebagai ganti 이/가 (할머니께서 웃으세요).',"ko-g56-u09.g.0":"Nenek, silakan makan.","ko-g56-u09.g.1":"Kakek ada di kamarnya.","ko-g56-u09.g.2":"Selamat tidur, Nenek.","ko-g56-u09.g.3":"Aku memberikan surat kepada guruku.","ko-g56-u09.g.4":"Nenek sedang tersenyum.","ko-g56-u09.g.5":"Aku pergi ke rumah Kakek.","ko-g56-u09.g.5.task":"Pakai kata hormat untuk rumah orang yang lebih tua: 댁.","ko-g56-u09.g.6":"Nenekmu umurnya berapa?","ko-g56-u09.g.6.task":"Pakai kata hormat untuk umur orang yang lebih tua: 연세.","ko-g56-u09.g.7":"Aku memberi Ayah hadiah.","ko-g56-u09.g.7.task":"Pakai kata kerja hormat untuk memberi kepada orang yang lebih tua: 드려요.","ko-g56-u09.r.ko":"Di rumah Nenek","ko-g56-u09.r.genre":"Cerita","ko-g56-u09.r.p.0":'Hari Sabtu, Hajun pergi ke rumah neneknya di desa. Nenek sedang menunggu di depan pintu. "Halo, Nenek!" sapa Hajun dengan suara keras.',"ko-g56-u09.r.p.1":'Malam harinya Nenek membuat sup tauco yang lezat. Hajun memberikan sendok kepada Nenek. "Nenek, silakan makan." Nenek tersenyum dan berkata, "Cucuku memang yang terbaik!"',"ko-g56-u09.r.p.2":'Malam itu Nenek menceritakan dongeng zaman dulu. Hajun tertidur sambil mendengarkan. Nenek menyelimutinya. "Tidur yang nyenyak, anak anjingku sayang."',"ko-g56-u09.r.q.2.o.0":"cucu","ko-g56-u09.r.q.2.o.1":"nenek","ko-g56-u09.r.q.2.o.2":"tetangga","ko-g56-u10.title":"Coba, deh","ko-g56-u10.tip":"Tanyakan pengalaman keluargamu: 한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"pengalaman","ko-g56-u10.w.1":"pertama kali","ko-g56-u10.w.2":"sekali","ko-g56-u10.w.3":"rasa","ko-g56-u10.w.4":"bau","ko-g56-u10.w.5":"menakjubkan","ko-g56-u10.w.6":"bibimbap","ko-g56-u10.w.7":"taekwondo","ko-g56-u10.w.8":"rumah tradisional Korea","ko-g56-u10.w.9":"memakai (sepatu, kaus kaki)","ko-g56-u10.w.10":"bagaimana?","ko-g56-u10.w.11":"wahana (di taman hiburan)","ko-g56-u10.s.0":"Coba kimchi ini juga.","ko-g56-u10.s.1":"Kamu pernah mencoba tteokbokki?","ko-g56-u10.s.2":"Ya, aku pernah mencobanya sekali.","ko-g56-u10.s.3":"Coba pakai topi ini.","ko-g56-u10.s.4":"Aku ingin mencoba belajar taekwondo.","ko-g56-u10.s.5":"Aku tidur di hanok untuk pertama kali.","ko-g56-u10.s.6":"Bagaimana rasanya?","ko-g56-u10.s.7":"Itu pengalaman yang benar-benar menakjubkan.","ko-g56-u10.g.title":"Coba: -아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":'Tambahkan 보세요 ke bentuk -아/어 untuk berkata "coba lakukan": 먹어 보세요 (Coba makan), 입어 보세요 (Coba pakai).',"ko-g56-u10.g.x.1":"봤어요 artinya kamu pernah mencobanya: 먹어 봤어요 (Aku pernah memakannya).","ko-g56-u10.g.x.2":"Tanyakan pengalaman dengan 봤어요?: 한국에 가 봤어요? — Kamu pernah ke Korea?","ko-g56-u10.g.0":"Coba kue beras ini.","ko-g56-u10.g.1":"Coba pakai baju ini.","ko-g56-u10.g.2":"Kamu pernah mencoba bibimbap?","ko-g56-u10.g.3":"Aku pernah ke Korea.","ko-g56-u10.g.4":"Coba belajar taekwondo.","ko-g56-u10.g.5":"Aku pernah tidur di hanok.","ko-g56-u10.g.5.task":"Katakan kamu pernah mengalaminya: pakai -아 봤어요.","ko-g56-u10.g.6":"Coba pakai sepatu ini.","ko-g56-u10.g.6.task":"Ajak mereka mencoba: pakai -어 보세요.","ko-g56-u10.g.7":"Kamu pernah naik wahana itu?","ko-g56-u10.g.7.task":"Tanyakan pengalamannya: pakai -아 봤어요?","ko-g56-u11.title":"Bagaimana kalau kita …?","ko-g56-u11.tip":"Di Korea, makanan bisa diantar hampir ke mana saja — bahkan ke taman di tepi sungai!","ko-g56-u11.w.0":"piknik, tamasya","ko-g56-u11.w.1":"bekal makan","ko-g56-u11.w.2":"tikar piknik","ko-g56-u11.w.3":"ayam goreng","ko-g56-u11.w.4":"pesan antar","ko-g56-u11.w.5":"Sungai Han","ko-g56-u11.w.6":"menerbangkan (layang-layang)","ko-g56-u11.w.7":"meminjam, menyewa","ko-g56-u11.w.8":"memesan (makanan)","ko-g56-u11.w.9":"bersama","ko-g56-u11.w.10":"pemandangan","ko-g56-u11.w.11":"cahaya senja","ko-g56-u11.s.0":"Besok kita ke taman, yuk?","ko-g56-u11.s.1":"Kita ketemu jam berapa?","ko-g56-u11.s.2":"Kita pesan piza, yuk?","ko-g56-u11.s.3":"Kita main layang-layang bersama, yuk?","ko-g56-u11.s.4":"Kita gelar tikarnya di sini, yuk?","ko-g56-u11.s.5":"Kami main layang-layang di Sungai Han.","ko-g56-u11.s.6":"Senjanya indah sekali.","ko-g56-u11.s.7":"Hari ini kita makan apa, ya?","ko-g56-u11.g.title":"Bagaimana kalau kita …?: -(으)ㄹ까요?","ko-g56-u11.g.x.0":"Untuk mengajak melakukan sesuatu bersama, buang 다 lalu tambahkan ㄹ까요?: 가다 → 갈까요? (Kita pergi, yuk?)","ko-g56-u11.g.x.1":"Sesudah huruf bawah, tambahkan 을까요?: 먹다 → 먹을까요?, 앉다 → 앉을까요?","ko-g56-u11.g.x.2":"Jawab dengan 네, 좋아요! atau usulkan hal lain dengan bentuk 요: 공원에 가요! (Ayo ke taman!)","ko-g56-u11.g.0":"Akhir pekan ini kita piknik, yuk?","ko-g56-u11.g.1":"Kita makan apa, ya?","ko-g56-u11.g.2":"Kita ketemu di mana?","ko-g56-u11.g.3":"Kita naik sepeda bersama, yuk?","ko-g56-u11.g.4":"Kita duduk di sini, yuk?","ko-g56-u11.g.5":"Kita pesan ayam goreng, yuk?","ko-g56-u11.g.5.task":"Ubah jadi ajakan: pakai -을까요?","ko-g56-u11.g.6":"Kita main layang-layang di Sungai Han, yuk?","ko-g56-u11.g.6.task":"Ubah jadi ajakan: pakai -ㄹ까요?","ko-g56-u11.g.7":"Hari ini kita ke perpustakaan bersama, yuk?","ko-g56-u11.g.7.task":"Ubah jadi ajakan: pakai -ㄹ까요?","ko-g56-u11.r.ko":"Piknik di Sungai Han","ko-g56-u11.r.genre":"Buku harian","ko-g56-u11.r.p.0":"Minggu, 3 Oktober. Cuacanya cerah. Keluargaku pergi piknik ke Sungai Han. Ibu menyiapkan bekal gimbap untuk kami.","ko-g56-u11.r.p.1":'Ayah bertanya, "Bagaimana kalau kita sewa sepeda?" Kami naik sepeda di sepanjang sungai. Anginnya sejuk, jadi rasanya enak sekali.',"ko-g56-u11.r.p.2":"Saat makan siang, kami menggelar tikar dan makan bekal. Adikku bilang dia juga ingin ayam. Jadi kami memesan antar ayam. Ternyata makanan bisa diantar sampai ke Sungai Han, menakjubkan sekali.","ko-g56-u11.r.p.3":"Sore harinya kami bermain layang-layang dan menonton matahari terbenam. Langit berubah merah dan sangat indah. Aku ingin datang lagi akhir pekan depan.","ko-g56-u11.r.q.3.o.0":"langit merah saat senja","ko-g56-u11.r.q.3.o.1":"layang-layang","ko-g56-u11.r.q.3.o.2":"tikar piknik","ko-g56-u12.title":"Tolong jangan","ko-g56-u12.tip":"Di Korea kamu akan melihat -지 마세요 di papan tanda: 만지지 마세요 (Jangan sentuh), 들어가지 마세요 (Dilarang masuk).","ko-g56-u12.w.0":"berisik, mengobrol","ko-g56-u12.w.1":"menyentuh","ko-g56-u12.w.2":"membuang","ko-g56-u12.w.3":"sampah","ko-g56-u12.w.4":"berbahaya","ko-g56-u12.w.5":"khawatir","ko-g56-u12.w.6":"keisengan","ko-g56-u12.w.7":"galeri seni","ko-g56-u12.w.8":"karya seni","ko-g56-u12.w.9":"memotret, merekam","ko-g56-u12.w.10":"makanan (dan minuman)","ko-g56-u12.w.11":"terburu-buru","ko-g56-u12.s.0":"Jangan berisik di perpustakaan.","ko-g56-u12.s.1":"Jangan sentuh lukisannya.","ko-g56-u12.s.2":"Jangan buang sampah di jalan.","ko-g56-u12.s.3":"Jangan terlalu khawatir.","ko-g56-u12.s.4":"Jangan berlari di jalan raya. Berbahaya.","ko-g56-u12.s.5":"Jangan terburu-buru di tangga.","ko-g56-u12.s.6":"Jangan memotret di galeri seni.","ko-g56-u12.s.7":"Jangan iseng kepada temanmu.","ko-g56-u12.g.title":"Jangan: -지 마세요","ko-g56-u12.g.x.0":"Untuk meminta seseorang dengan sopan agar tidak melakukan sesuatu, buang 다 lalu tambahkan 지 마세요: 만지다 → 만지지 마세요 (Jangan sentuh).","ko-g56-u12.g.x.1":"Caranya sama untuk semua kata kerja: 먹지 마세요, 뛰지 마세요, 걱정하지 마세요.","ko-g56-u12.g.x.2":"Kepada teman dekat, kamu bisa bilang -지 마: 울지 마! (Jangan menangis!)","ko-g56-u12.g.0":"Jangan sentuh karya seninya.","ko-g56-u12.g.1":"Jangan khawatir.","ko-g56-u12.g.2":"Jangan berisik di kelas.","ko-g56-u12.g.3":"Jangan berlari di jalan raya.","ko-g56-u12.g.4":"Jangan makan di sini.","ko-g56-u12.g.5":"Jangan buang sampah sembarangan.","ko-g56-u12.g.5.task":'Ubah jadi "jangan": pakai -지 마세요.',"ko-g56-u12.g.6":"Jangan memotret di galeri seni.","ko-g56-u12.g.6.task":'Ubah jadi "jangan": pakai -지 마세요.',"ko-g56-u12.g.7":"Jangan terburu-buru.","ko-g56-u12.g.7.task":'Ubah jadi "jangan": pakai -지 마세요.',"ko-g56-u13.title":"Sebelum dan sesudah","ko-g56-u13.tip":"Masak gimbap (atau makanan sederhana apa saja) bersama keluargamu dan ucapkan setiap langkah dalam bahasa Korea: 먼저 …, 그다음에 …, 마지막으로 …","ko-g56-u13.w.0":"bahan-bahan","ko-g56-u13.w.1":"rumput laut kering","ko-g56-u13.w.2":"meratakan","ko-g56-u13.w.3":"menggulung","ko-g56-u13.w.4":"mengiris","ko-g56-u13.w.5":"pisau","ko-g56-u13.w.6":"mengaduk","ko-g56-u13.w.7":"minyak wijen","ko-g56-u13.w.8":"ham","ko-g56-u13.w.9":"acar lobak kuning","ko-g56-u13.w.10":"terakhir","ko-g56-u13.w.11":"berhati-hati","ko-g56-u13.s.0":"Aku membaca buku sebelum tidur.","ko-g56-u13.s.1":"Aku makan camilan sesudah bersih-bersih.","ko-g56-u13.s.2":"Aku sarapan sebelum berangkat sekolah.","ko-g56-u13.s.3":"Aku mandi sesudah berenang.","ko-g56-u13.s.4":"Aku mencuci bahan-bahan sebelum memasak.","ko-g56-u13.s.5":"Ratakan nasi di atas rumput laut.","ko-g56-u13.s.6":"Hati-hati saat memakai pisau.","ko-g56-u13.s.7":"Terakhir, iris gimbapnya.","ko-g56-u13.g.title":"Sebelum dan sesudah: -기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":'"Sebelum melakukan": buang 다 lalu tambahkan 기 전에: 먹다 → 먹기 전에 (sebelum makan).',"ko-g56-u13.g.x.1":'"Sesudah melakukan": buang 다 lalu tambahkan ㄴ 후에: 하다 → 한 후에. Sesudah huruf bawah, tambahkan 은 후에: 먹다 → 먹은 후에.',"ko-g56-u13.g.x.2":"Dengan kata benda, cukup tambahkan 전에 atau 후에: 수업 전에, 방학 후에.","ko-g56-u13.g.0":"Aku mencuci tangan sebelum makan.","ko-g56-u13.g.1":"Aku bermain sesudah mengerjakan PR.","ko-g56-u13.g.2":"Aku menyikat gigi sebelum tidur.","ko-g56-u13.g.3":"Aku jalan-jalan sesudah makan.","ko-g56-u13.g.4":"Sesudah pulang sekolah, aku pergi latihan taekwondo.","ko-g56-u13.g.5":"Sebelum membuat gimbap, kami menyiapkan bahan-bahannya.","ko-g56-u13.g.5.task":"Pakai -기 전에 untuk membuat satu kalimat.","ko-g56-u13.g.6":"Kami makan sesudah menonton film.","ko-g56-u13.g.6.task":"Pakai -ㄴ 후에 untuk membuat satu kalimat.","ko-g56-u13.g.7":"Aku memakai piyama sesudah mandi.","ko-g56-u13.g.7.task":"Pakai -ㄴ 후에 untuk membuat satu kalimat.","ko-g56-u13.r.ko":"Ayo membuat gimbap","ko-g56-u13.r.genre":"Resep","ko-g56-u13.r.p.0":"Gimbap adalah makanan yang sering dimakan orang Korea saat piknik. Hari ini aku akan membuat gimbap bersama Ibu. Sebelum mulai, aku mencuci tangan dengan bersih.","ko-g56-u13.r.p.1":"Pertama, siapkan bahan-bahannya. Kamu butuh rumput laut, nasi, telur, ham, acar lobak, dan bayam. Masukkan garam dan minyak wijen ke nasi lalu aduk. Ibu memotong ham dan telur memanjang dengan pisau. Pisau itu berbahaya, jadi orang dewasa yang harus memakainya.","ko-g56-u13.r.p.2":"Ratakan nasi tipis-tipis di atas rumput laut. Sesudah menaruh isiannya di atas, gulung dengan rapat. Terakhir, Ibu mengiriskan gimbapnya untukku. Gimbap buatanku enak sekali!","ko-g56-u14.title":"Bicara dengan teman","ko-g56-u14.tip":"Di Korea, kamu hanya boleh memakai 반말 dengan orang yang akrab dan kira-kira seumuran. Kalau ragu, tetap pakai 요 — itu selalu aman.","ko-g56-u14.w.0":"bahasa santai","ko-g56-u14.w.1":"akrab (berteman)","ko-g56-u14.w.2":"iya (santai)","ko-g56-u14.w.3":"nggak (santai)","ko-g56-u14.w.4":"makasih (santai)","ko-g56-u14.w.5":"maaf ya (santai)","ko-g56-u14.w.6":"nggak apa-apa (santai)","ko-g56-u14.w.7":"lagi ngapain? (santai)","ko-g56-u14.w.8":"ayo main","ko-g56-u14.w.9":"beneran (santai)","ko-g56-u14.w.10":"hubungan","ko-g56-u14.w.11":"seumuran","ko-g56-u14.s.0":"Kita seumuran, nggak?","ko-g56-u14.s.1":"Iya, aku juga sepuluh tahun.","ko-g56-u14.s.2":"Hari ini kamu mau ngapain?","ko-g56-u14.s.3":"Ayo ke rumahku!","ko-g56-u14.s.4":"Maaf ya soal yang tadi.","ko-g56-u14.s.5":"Nggak apa-apa, jangan khawatir.","ko-g56-u14.s.6":"Lagu ini bagus banget!","ko-g56-u14.s.7":"Kita memakai bahasa sopan dengan guru.","ko-g56-u14.g.title":"Bahasa santai dengan teman: buang 요","ko-g56-u14.g.x.0":"Dengan teman akrab dan anak yang lebih muda, orang Korea memakai 반말 (bahasa santai). Biasanya cukup buang 요: 가요 → 가, 먹어요 → 먹어.","ko-g56-u14.g.x.1":"이에요/예요 menjadi 이야/야: 학생이에요 → 학생이야, 친구예요 → 친구야.","ko-g56-u14.g.x.2":'"Ayo …" kepada teman adalah -자: 가자! 먹자! 놀자! Lalu 네 → 응, 아니요 → 아니.',"ko-g56-u14.g.x.3":"Selalu pakai 요 dengan orang dewasa, guru, dan orang yang baru kamu kenal!","ko-g56-u14.g.0":"Kamu lagi ngapain sekarang?","ko-g56-u14.g.1":"Aku juga sepuluh tahun.","ko-g56-u14.g.2":"Ini temanku.","ko-g56-u14.g.3":"Ayo makan bareng!","ko-g56-u14.g.4":"Maaf ya aku telat.","ko-g56-u14.g.5":"Ayo main bareng!","ko-g56-u14.g.5.task":"Katakan kepada teman akrab: pakai -자.","ko-g56-u14.g.6":"Game ini seru banget!","ko-g56-u14.g.6.task":"Katakan kepada teman akrab: buang 요 dan pakai 진짜.","ko-g56-u14.g.7":"Aku murid.","ko-g56-u14.g.7.task":"Katakan dalam 반말: 저는 → 나는, 이에요 → 이야.","ko-g56-u15.title":"Saat …: -(으)ㄹ 때","ko-g56-u15.tip":"Bicarakan perasaan dengan -ㄹ 때: 기쁠 때 노래해요. 슬플 때 엄마를 안아요. Kamu ngapain kalau sedang bosan?","ko-g56-u15.w.0":"mengantuk","ko-g56-u15.w.1":"haus","ko-g56-u15.w.2":"penasaran","ko-g56-u15.w.3":"kesal","ko-g56-u15.w.4":"kesepian","ko-g56-u15.w.5":"berat, sulit","ko-g56-u15.w.6":"menghibur","ko-g56-u15.w.7":"sendirian","ko-g56-u15.w.8":"pikiran","ko-g56-u15.w.9":"kenangan","ko-g56-u15.w.10":"waktu aku kecil","ko-g56-u15.w.11":"ruang karaoke","ko-g56-u15.s.0":"Saat bosan, aku menggambar.","ko-g56-u15.s.1":"Saat lapar, aku makan apel.","ko-g56-u15.s.2":"Saat penasaran, aku bertanya kepada guru.","ko-g56-u15.s.3":"Saat temanku kesal, aku menghiburnya.","ko-g56-u15.s.4":"Saat sendirian, aku membaca buku.","ko-g56-u15.s.5":"Waktu aku kecil, aku tinggal di desa.","ko-g56-u15.s.6":"Saat keadaan sulit, aku memikirkan temanku.","ko-g56-u15.s.7":"Aku senang sekali saat pergi karaoke.","ko-g56-u15.g.title":"Saat: -(으)ㄹ 때","ko-g56-u15.g.x.0":'Untuk berkata "saat (sesuatu terjadi)", buang 다 lalu tambahkan ㄹ 때: 졸리다 → 졸릴 때 (saat aku mengantuk).',"ko-g56-u15.g.x.1":"Sesudah huruf bawah, tambahkan 을 때: 먹다 → 먹을 때, 있다 → 있을 때.","ko-g56-u15.g.x.2":"Untuk masa lampau, pakai 았/었을 때: 어렸을 때 (waktu aku kecil). Dengan kata benda, cukup tambahkan 때: 방학 때, 점심 때.","ko-g56-u15.g.0":"Saat mengantuk, aku cuci muka.","ko-g56-u15.g.1":"Jangan bicara saat makan.","ko-g56-u15.g.2":"Saat sendirian, aku mendengarkan musik.","ko-g56-u15.g.3":"Kalau penasaran, bertanyalah.","ko-g56-u15.g.4":"Saat liburan, aku pergi ke rumah nenek.","ko-g56-u15.g.5":"Saat haus, aku minum air.","ko-g56-u15.g.5.task":"Pakai -ㄹ 때 untuk membuat satu kalimat.","ko-g56-u15.g.6":"Saat aku kesal, Ibu menghiburku.","ko-g56-u15.g.6.task":"Pakai -ㄹ 때 untuk membuat satu kalimat.","ko-g56-u15.g.7":"Waktu aku kecil, aku tinggal di desa.","ko-g56-u15.g.7.task":"Pakai -았/었을 때 untuk membuat satu kalimat.","ko-g56-u16.title":"Bercerita","ko-g56-u16.tip":"Heungbu dan Nolbu adalah salah satu dongeng rakyat Korea yang paling terkenal. Ceritakan lagi kepada keluargamu dengan 먼저, 그다음에, 그런데, dan 마지막으로!","ko-g56-u16.w.0":"pertama","ko-g56-u16.w.1":"lalu, berikutnya","ko-g56-u16.w.2":"tapi, lalu","ko-g56-u16.w.3":"tiba-tiba","ko-g56-u16.w.4":"akhirnya, terakhir","ko-g56-u16.w.5":"keserakahan","ko-g56-u16.w.6":"miskin","ko-g56-u16.w.7":"orang kaya","ko-g56-u16.w.8":"burung layang-layang","ko-g56-u16.w.9":"biji","ko-g56-u16.w.10":"labu","ko-g56-u16.w.11":"harta karun","ko-g56-u16.s.0":"Pertama, aku mengerjakan PR.","ko-g56-u16.s.1":"Lalu, aku bermain dengan anak anjing.","ko-g56-u16.s.2":"Terakhir, aku menulis buku harian.","ko-g56-u16.s.3":"Kami pergi piknik. Tapi kami lupa membawa bekal.","ko-g56-u16.s.4":"Tiba-tiba seekor anak anjing berlari datang.","ko-g56-u16.s.5":"Perutku sakit. Jadi aku pergi ke rumah sakit.","ko-g56-u16.s.6":"Nolbu sangat serakah.","ko-g56-u16.s.7":"Harta karun keluar dari labu.","ko-g56-u16.g.title":"Bercerita berurutan: 먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"Pakai kata-kata ini di awal kalimat untuk bercerita secara berurutan: 먼저 (pertama) → 그다음에 (lalu) → 마지막으로 (terakhir).","ko-g56-u16.g.x.1":'그래서 artinya "jadi" (akibat): 비가 와요. 그래서 집에 있어요.',"ko-g56-u16.g.x.2":'그런데 artinya "tapi" atau "lalu" (sesuatu yang tak terduga): 공원에 갔어요. 그런데 문이 닫혀 있었어요.',"ko-g56-u16.g.x.3":'갑자기 artinya "tiba-tiba": 갑자기 불이 꺼졌어요.',"ko-g56-u16.g.0":"Pertama, cuci tanganmu.","ko-g56-u16.g.1":"Lalu, makanlah.","ko-g56-u16.g.2":"Hujan turun. Jadi aku memakai payung.","ko-g56-u16.g.3":"Aku pergi ke taman. Tapi lalu hujan turun.","ko-g56-u16.g.4":"Terakhir, sikat gigimu.","ko-g56-u16.g.5":"Aku lapar. Jadi aku makan roti.","ko-g56-u16.g.5.task":"Pisahkan menjadi dua kalimat dengan 그래서.","ko-g56-u16.g.6":"Aku sedang berjalan. Tiba-tiba hujan turun.","ko-g56-u16.g.6.task":'Tambahkan "tiba-tiba": pakai 갑자기.',"ko-g56-u16.g.7":"Pertama aku mengerjakan PR. Lalu aku bermain.","ko-g56-u16.g.7.task":"Ceritakan dalam dua langkah: 먼저 … 그다음에 …","ko-g56-u16.r.ko":"Heungbu dan Nolbu","ko-g56-u16.r.genre":"Dongeng rakyat","ko-g56-u16.r.p.0":"Dahulu kala, hiduplah dua bersaudara, Heungbu dan Nolbu. Sang kakak, Nolbu, kaya tapi sangat serakah. Sang adik, Heungbu, miskin tapi baik hati.","ko-g56-u16.r.p.1":"Suatu hari di musim semi, Heungbu melihat seekor burung layang-layang yang kakinya terluka. Ia mengobati kaki burung itu dengan hati-hati. Ketika musim gugur tiba, burung layang-layang itu terbang ke selatan yang hangat.","ko-g56-u16.r.p.2":"Musim semi berikutnya, burung layang-layang itu kembali sambil membawa biji labu. Ketika Heungbu menanamnya, tumbuhlah labu-labu raksasa. Ketika ia membelah sebuah labu, emas dan harta karun berhamburan keluar!","ko-g56-u16.r.p.3":"Ketika Nolbu mendengar cerita itu, ia sengaja melukai kaki seekor burung layang-layang. Tetapi dari labu-labu Nolbu keluar para goblin yang menghukumnya. Akhirnya Nolbu menyesali perbuatannya dan menjadi orang baik.","ko-g56-u16.r.q.3.o.0":"keserakahan","ko-g56-u16.r.q.3.o.1":"kebaikan hati","ko-g56-u16.r.q.3.o.2":"harta karun"},i={"tier.first.label":"Kata Pertama","tier.first.age":"Walau belum bisa membaca","tier.first.desc":"Dengar kata, ketuk gambar · tidak perlu membaca","tier.kinder.label":"Hangul","tier.kinder.age":"Mulai di sini jika baru","tier.kinder.desc":"Huruf Korea dan cara menggabungkannya · salam, angka, warna","tier.g12.label":"Kalimat Pertama","tier.g12.age":"Jika bisa membaca Hangul","tier.g12.desc":"Makanan, tubuh, sekolah, cuaca · kalimat pendek","tier.g34.label":"Dasar Tata Bahasa","tier.g34.age":"Jika tahu kalimat pendek","tier.g34.desc":"Partikel, akhiran kata kerja, lampau dan masa depan · percakapan","tier.g56.label":"Membaca","tier.g56.age":"Jika bisa membuat kalimat","tier.g56.desc":"Bisa, harus, bahasa sopan · bacaan pendek"},e={...i,...a,...k,...u,...n,...g};export{e as default};
